  {t="C", seg=2, q={371,374}, names={"At War With The Scarlet Crusade","Proof of Demise"}, text="Scarlet Watch Post just north of Balnir: kill Captain Vachon and 5 Scarlet Friars, and finish the 10 Scarlet Insignia Rings", zone="Tirisfal Glades", map=1420, x=79.1, y=55.9},
