  {t="T", seg=2, q={371,99141}, names={"At War With The Scarlet Crusade","Patience"}, text="Executor Zygand. Do not take the next Scarlet quest (level 12)", zone="Tirisfal Glades", map=1420, x=60.6, y=51.8},
  {t="A", seg=2, q={398}, names={"Wanted: Maggot Eye"}, text="The Wanted poster next to Zygand. You kill Maggot Eye at the end of this segment, once you have Frost Nova", zone="Tirisfal Glades", map=1420, x=60.7, y=51.6},
