  {t="T", seg=2, q={492}, names={"A New Plague"}, text="Tavern cellar: give Johaan's drink to the Captured Mountaineer", zone="Tirisfal Glades", map=1420, x=61.9, y=51.4},
  {t="L", seg=2, lvl=10, text="Not level 10 after these turn-ins? Kill duskbats and darkhounds in the woods east of Brill until you are; the Vampiric Duskbats out toward Brightwater Lake give the most XP. The next three steps need level 10", zone="Tirisfal Glades", map=1420, x=70.5, y=52.0},
  {t="TRAIN", seg=2, text="Cain Firesong, upstairs: learn your level 10 spells (Frost Nova, Frost Armor rank 2, Conjure Water rank 2)"},
  {t="A", seg=2, q={1881}, names={"Speak with Anastasia"}, text="Cain Firesong (needs level 10)", zone="Tirisfal Glades", map=1420, x=62.0, y=52.5},
  {t="A", seg=2, q={96895}, names={"The Argent Emissary"}, text="Deathguard Terrence, at the south edge of Brill (needs level 10)", zone="Tirisfal Glades", map=1420, x=61.5, y=53.5},
  {t="T", seg=2, q={96895}, names={"The Argent Emissary"}, text="Hadric Harlson at the waystation camp south-east of Brill", zone="Tirisfal Glades", map=1420, x=65.9, y=61},
  {t="A", seg=2, q={96897,96898}, names={"The Cult of the Damned","Remnants of War"}, text="Hadric now offers two new Argent Dawn quests, The Cult of the Damned and Remnants of War (level 13). You do them right after the Undercity", zone="Tirisfal Glades", map=1420, x=65.9, y=61.0},
  {t="N", seg=2, arg="Shelene Rhobart, next to Hadric, may offer the new Forever quest Hides for the Forsaken. It is not on this route: take it so the logger records it, and abandon it if you will not do it"},
  {t="G", seg=2, text="Walk south-west into the Ruins of Lordaeron and enter the Undercity through the throne room at the back. Ride an elevator down and follow the signs to the Magic Quarter", zone="Tirisfal Glades", map=1420, x=60.5, y=66.5},
  {t="T", seg=2, q={405}, names={"The Prodigal Lich"}, text="Bethor Iceshard in the Magic Quarter", zone="Undercity", map=1458, x=83.9, y=17.2},
  {t="A", seg=2, q={357}, names={"The Lich's Identity"}, zone="Undercity", map=1458, x=83.9, y=17.2},
  {t="T", seg=2, q={1881}, names={"Speak with Anastasia"}, text="Anastasia Hartwell, also in the Magic Quarter", zone="Undercity", map=1458, x=85, y=10.4},
  {t="A", seg=2, q={1882}, names={"The Balnir Farmstead"}, text="Keep this quest: you hand it in on the next Undercity visit (segment 3)", zone="Undercity", map=1458, x=85, y=10.4},
  {t="C", seg=2, q={96897,96898}, names={"The Cult of the Damned","Remnants of War"}, text="Leave the Undercity and go to the cultist camp just south-east of Hadric: kill 8 Dark Neophytes and 8 Dark Enforcers and collect 12 Necrotic Crystal Fragments in the same camp. Pull one cultist at a time. If they are 3 or more levels above you, abandon both quests: you pass this camp again at the end of the next segment and can take them then", zone="Tirisfal Glades", map=1420, x=68.0, y=64.8},
  {t="T", seg=2, q={96897,96898}, names={"The Cult of the Damned","Remnants of War"}, text="Back to Hadric. Skip his next quest, Bandarion Keep: it sends you far to the west", zone="Tirisfal Glades", map=1420, x=65.9, y=61.0},
  {t="C", seg=2, q={1882}, names={"The Balnir Farmstead"}, text="Go east to Balnir Farmstead: pick a Balnir Snapdragon", zone="Tirisfal Glades", map=1420, x=77.5, y=61.9},
  {t="C", seg=2, q={357}, names={"The Lich's Identity"}, text="Gunther's Retreat, the small island in Brightwater Lake north-west of Balnir: swim over and take the Lich's Spellbook from Gunther's bookshelf. Gunther is friendly. Keep the quest for Bethor (segment 3)", zone="Tirisfal Glades", map=1420, x=68.0, y=42.1},
  {t="C", seg=2, q={398}, names={"Wanted: Maggot Eye"}, text="Swim to the north-west shore and go to Garren's Haunt, the gnoll camp north of Brill. Maggot Eye (level 11) stands at its north end: clear the gnolls around him, open with Frostbolt from max range, and Frost Nova him and step back if he reaches you", zone="Tirisfal Glades", map=1420, x=58.7, y=30.8},
  {t="T", seg=2, q={398}, names={"Wanted: Maggot Eye"}, text="Walk south to Brill: Executor Zygand", zone="Tirisfal Glades", map=1420, x=60.6, y=51.8, path={{60.0,30.7},{62.2,33.7},{62.2,40.0},{63.4,41.8},{63.4,46.9},{60.6,48.7}}},
  {t="A", seg=2, q={445}, names={"Delivery to Silverpine Forest"}, text="Apothecary Johaan", zone="Tirisfal Glades", map=1420, x=59.5, y=52.4},
  {t="N", seg=2, arg="Done in Tirisfal for now. Next segment: leave Brill on the road south toward the Undercity and branch west into Silverpine Forest"},
  {t="N", seg=3, arg="Leave Brill on the road south toward the Undercity, then branch west into Silverpine Forest", text="The road enters Silverpine in its north-east corner. Follow it to Malden's Orchard, where Deathstalker Erland waits in a farmhouse."},
  {t="A", seg=3, q={435}, names={"Escorting Erland"}, text="Deathstalker Erland, Malden's Orchard", zone="Silverpine Forest", map=1421, x=56.2, y=9.1},
  {t="C", seg=3, q={435}, names={"Escorting Erland"}, text="Escort Erland west to Rane Yorick. Worgs attack along the way: Frost Nova them and keep Erland alive.", zone="Silverpine Forest", map=1421, x=56.2, y=9.2},
  {t="T", seg=3, q={435}, names={"Escorting Erland"}, text="Rane Yorick at the Ivar Patch farm", zone="Silverpine Forest", map=1421, x=53.5, y=13.4},
  {t="A", seg=3, q={449}, names={"The Deathstalkers' Report"}, text="Rane Yorick: the report goes to High Executor Hadrec at the Sepulcher.", zone="Silverpine Forest", map=1421, x=53.5, y=13.4},
  {t="A", seg=3, q={429}, names={"Wild Hearts"}, text="Rane Yorick: Wild Hearts. He offers it as soon as the escort is handed in.", zone="Silverpine Forest", map=1421, x=53.5, y=13.4},
  {t="N", seg=3, arg="Follow the road south to the Sepulcher", text="It is the crypt hill west of the road, about halfway down the zone. If you have Wild Hearts, kill the Mottled Worgs near the road on the way for Discolored Worg Hearts; you finish them on the next trip north."},
  {t="T", seg=3, q={449}, names={"The Deathstalkers' Report"}, text="High Executor Hadrec, inside the Sepulcher", zone="Silverpine Forest", map=1421, x=43.4, y=40.8},
  {t="A", seg=3, q={3221,437}, names={"Speak with Renferrel","The Dead Fields"}, text="Hadrec", zone="Silverpine Forest", map=1421, x=43.4, y=40.8},
  {t="T", seg=3, q={445,3221}, names={"Delivery to Silverpine Forest","Speak with Renferrel"}, text="Apothecary Renferrel, beside Hadrec", zone="Silverpine Forest", map=1421, x=42.9, y=40.9},
  {t="A", seg=3, q={447,1359}, names={"A Recipe For Death","Zinge's Delivery"}, text="Renferrel. Zinge's Delivery is only a hand-in in the Undercity at the end of this segment.", zone="Silverpine Forest", map=1421, x=42.8, y=40.9},
  {t="A", seg=3, q={6321}, names={"Supplying the Sepulcher"}, text="Deathguard Podrig, just outside the crypts", zone="Silverpine Forest", map=1421, x=43.5, y=41.7},
