  {t="A", seg=3, q={6323}, names={"Ride to the Undercity"}, text="Do not buy the bat ride. You hand this in on foot in the Undercity at the end of the segment.", zone="Silverpine Forest", map=1421, x=45.6, y=42.5},
  {t="T", seg=3, q={477}, names={"Border Crossings"}, text="Follow the road south toward Pyrewood. The crate is at the Dalaran apprentices' camp; the apprentices are level 13-14, so pull them one at a time. Kill grizzled bears on the way: their hearts count for A Recipe For Death.", zone="Silverpine Forest", map=1421, x=49.8, y=60.4},
  {t="A", seg=3, q={478}, names={"Maps and Runes"}, text="From the same crate", zone="Silverpine Forest", map=1421, x=49.8, y=60.4},
  {t="T", seg=3, q={478}, names={"Maps and Runes"}, text="Back at the Sepulcher: Shadow Priest Allister", zone="Silverpine Forest", map=1421, x=44, y=41},
  {t="A", seg=3, q={481}, names={"Dalar's Analysis"}, text="Allister", zone="Silverpine Forest", map=1421, x=44, y=41},
