  {t="A", seg=3, q={95981}, names={"Watching the Roads"}, text="Allister. Level 20 (Dalaran wizards and watchers near Ambermill): keep it in your log for a later segment. If he does not offer it yet, pick it up on your next Sepulcher visit.", zone="Silverpine Forest", map=1421, x=44.0, y=40.9},
  {t="N", seg=3, arg="Head north on the road back toward the Ivar Patch", text="Kill the Ferocious Grizzled Bears along the road for Grizzled Bear Hearts as you go."},
  {t="C", seg=3, q={429}, names={"Wild Hearts"}, text="Kill Mottled Worgs around the Ivar Patch and Malden's Orchard for Discolored Worg Hearts. More worgs roam south toward the Dead Fields.", zone="Silverpine Forest", map=1421, x=57.5, y=11.0},
  {t="C", seg=3, q={437}, names={"The Dead Fields"}, text="The Dead Fields, west of the road: kill Rot Hide gnolls until Nightlash appears. Frost Nova and kite her, then loot the Essence of Nightlash.", zone="Silverpine Forest", map=1421, x=45.0, y=21.5},
  {t="C", seg=3, q={447}, names={"A Recipe For Death"}, text="Moss Stalker spiders on the north-west coast drop Skittering Blood. Giant Grizzled Bears between here and the Dead Fields drop the rest of the hearts.", zone="Silverpine Forest", map=1421, x=35.5, y=14.5},
  {t="T", seg=3, q={429}, names={"Wild Hearts"}, text="Back at the Sepulcher: Renferrel", zone="Silverpine Forest", map=1421, x=42.9, y=40.9},
