  {t="C", seg=3, q={425}, names={"Ivar the Foul"}, text="Ivar the Foul wanders the Ivar Patch farm. He is level 13: open with Frost Nova and kite him.", zone="Silverpine Forest", map=1421, x=51.5, y=13.9},
  {t="T", seg=3, q={425}, names={"Ivar the Foul"}, text="Rane Yorick", zone="Silverpine Forest", map=1421, x=53.5, y=13.4},
  {t="C", seg=3, q={91920}, names={"Wild Eyes"}, text="Kill Vile Fin murlocs on the lake shore east and south-east of the farm for Murloc Eyes.", zone="Silverpine Forest", map=1421, x=57.7, y=20.3},
  {t="T", seg=3, q={438}, names={"The Decrepit Ferry"}, text="The Decrepit Ferry is guarded by level 14-16 Ravenclaw undead: Hands of Ravenclaw beside the dock, Champions on the shore just north-west of it, Fenwick Thatros a little north-east. Do not walk down the shore path or onto the dock. Swim south through the lake from the murloc shore and click the Corpse Laden Boat from the water. If one aggros, Frost Nova it and swim back north.", zone="Silverpine Forest", map=1421, x=58.4, y=34.9},
  {t="A", seg=3, q={439}, names={"Rot Hide Clues"}, text="From the boat", zone="Silverpine Forest", map=1421, x=58.4, y=34.9},
