  {t="L", seg=3, lvl=12, text="Dalar's next quest needs level 12. If you are not 12 yet, kill Ferocious Grizzled Bears on the slope just east of the Sepulcher, down the hill along the road. Moonrage Whitescalps share the slope, but kills made before you take Dalar's quest do not count for it. Dalar is a short walk back up the hill.", zone="Silverpine Forest", map=1421, x=49.5, y=37.5},
  {t="A", seg=3, q={421}, names={"Prove Your Worth"}, text="Dalar Dawnweaver (needs level 12)", zone="Silverpine Forest", map=1421, x=44.2, y=39.9},
  {t="C", seg=3, q={421}, names={"Prove Your Worth"}, text="Moonrage Whitescalps roam just east of the Sepulcher, down the hill along the road.", zone="Silverpine Forest", map=1421, x=49.0, y=36.5},
  {t="T", seg=3, q={421}, names={"Prove Your Worth"}, text="Dalar", zone="Silverpine Forest", map=1421, x=44.1, y=39.7},
  {t="A", seg=3, q={422}, names={"Arugal's Folly"}, text="Dalar", zone="Silverpine Forest", map=1421, x=44.1, y=39.7},
  {t="C", seg=3, q={422}, names={"Arugal's Folly"}, text="The wheat farm by the lake, just north of the bridge: loot the Remedy of Arugal from the Dusty Spellbooks.", zone="Silverpine Forest", map=1421, x=52.8, y=28.6},
  {t="T", seg=3, q={91921}, names={"Return to Quinn (Again)"}, text="Quinn Yorick at the Ivar Patch", zone="Silverpine Forest", map=1421, x=53.4, y=12.7},
  {t="T", seg=3, q={422}, names={"Arugal's Folly"}, text="Back at the Sepulcher: Dalar", zone="Silverpine Forest", map=1421, x=44.2, y=39.8},
  {t="A", seg=3, q={423}, names={"Arugal's Folly"}, text="Dalar. Keep it for a later segment (Moonrage Gluttons and Darksouls).", zone="Silverpine Forest", map=1421, x=44.2, y=39.8},
  {t="G", seg=3, text="Optional: loot the book from the shelf here (a Forever collectible; you hand the books in later).", zone="Silverpine Forest", map=1421, x=43.4, y=41.3},
  {t="H", seg=3, arg="Brill", text="Your hearthstone has not been used since Tirisfal, so it should be ready. If it is not, buy a bat ride to the Undercity from Karos Razok, walk out of the Ruins and north up the road to Brill, then carry on with the steps below in order (Sevren first, then back down into the Undercity)."},
  {t="G", seg=3, text="Optional: another collectible book on the shelf next to Apothecary Johaan.", zone="Tirisfal Glades", map=1420, x=59.4, y=52.3},
  {t="T", seg=3, q={440}, names={"The Engraved Ring"}, text="Magistrate Sevren in the Brill town hall", zone="Tirisfal Glades", map=1420, x=61.2, y=50.8},
  {t="A", seg=3, q={441}, names={"Raleigh and the Undercity"}, text="Sevren", zone="Tirisfal Glades", map=1420, x=61.3, y=50.8},
  {t="N", seg=3, arg="Walk south to the Ruins of Lordaeron and take an elevator down into the Undercity"},
  {t="T", seg=3, q={6323}, names={"Ride to the Undercity"}, text="Gordon Wendham, the weapon vendor in the Trade Quarter", zone="Undercity", map=1458, x=61.6, y=42},
