  {t="T", seg=3, q={441}, names={"Raleigh and the Undercity"}, text="Raleigh Andrean, next to Gordon", zone="Undercity", map=1458, x=62, y=43},
  {t="A", seg=3, q={530}, names={"A Husband's Revenge"}, text="Raleigh. Level 20: keep it for a later segment.", zone="Undercity", map=1458, x=62, y=43},
  {t="T", seg=3, q={6322}, names={"Michael Garrett"}, text="Michael Garrett, the Undercity bat handler", zone="Undercity", map=1458, x=63.3, y=48.6},
