  {t="A", seg=3, q={97891}, names={"Prompt Potion Runner"}, text="Alessandro Luca. It is timed: run straight across the canal to the Apothecarium.", zone="Undercity", map=1458, x=58.5, y=55.3},
  {t="T", seg=3, q={97891}, names={"Prompt Potion Runner"}, text="Doctor Martin Felben in the Apothecarium", zone="Undercity", map=1458, x=46.4, y=74},
  {t="A", seg=3, q={5725}, names={"The Power to Destroy..."}, text="Varimathras in the Royal Quarter. Two books from the last two bosses of Ragefire Chasm.", zone="Undercity", map=1458, x=56.3, y=92.2, dg=1},
  {t="T", seg=3, q={447}, names={"A Recipe For Death"}, text="Master Apothecary Faranell", zone="Undercity", map=1458, x=48.7, y=69.6},
  {t="A", seg=3, q={450}, names={"A Recipe For Death"}, text="Faranell's follow-up: fetch a journal from the inn at Pyrewood Village. It is marked elite because of the village guards; the route picks it up as an optional stop on your next Silverpine trip (segment 5)", zone="Undercity", map=1458, x=48.7, y=69.6},
  {t="T", seg=3, q={1359}, names={"Zinge's Delivery"}, text="Apothecary Zinge, next to Faranell", zone="Undercity", map=1458, x=49.9, y=68},
  {t="A", seg=3, q={1358}, names={"Sample for Helbrim"}, text="Zinge. You hand it in at the Crossroads in the Barrens.", zone="Undercity", map=1458, x=49.9, y=68},
  {t="T", seg=3, q={357}, names={"The Lich's Identity"}, text="Bethor Iceshard in the Magic Quarter. Leave his follow-up for now.", zone="Undercity", map=1458, x=84, y=17.1},
  {t="T", seg=3, q={1882}, names={"The Balnir Farmstead"}, text="Anastasia Hartwell, at the top of the Magic Quarter. Pick the reward you prefer.", zone="Undercity", map=1458, x=85.2, y=10.4},
  {t="TRAIN", seg=3, text="Undercity Magic Quarter, learn your level 12 spells"},
  {t="N", seg=3, arg="Only if you abandoned Hadric Harlson's two Argent Dawn quests in Tirisfal: take them again at his waystation camp, just east of the zeppelin tower", text="The Cult of the Damned and Remnants of War (level 13). Kill 8 Dark Neophytes and 8 Dark Enforcers and pick up 12 Necrotic Crystal Fragments in the cultist area just south-east of the camp (66-70, 62-67), then hand both in to Hadric. Skip Bandarion Keep (it sends you far west). If you already handed them in, skip this step.", zone="Tirisfal Glades", map=1420, x=65.9, y=61.0},
  {t="A", seg=3, q={92422}, names={"The Wrath of Rath'mael"}, text="Deathguard Kristof in Brill. Only offered if you did Deathguard Linnea's Rear Guard Patrol quests; if he has nothing, press Skip.", zone="Tirisfal Glades", map=1420, x=65.2, y=60.2, dg=2},
