  {t="N", seg=4, arg="Optional dungeon: Ragefire Chasm, levels 13-18", text="The entrance is in Orgrimmar, in the Cleft of Shadow. Inside: the corpse of Maur Grimtotem gives the follow-up quest Returning the Lost Satchel. Quests you picked up for it: The Power to Destroy..., Hidden Enemies, Slaying the Beast. Not on your path, only if you want the detour: Searching for the Lost Satchel (Thunder Bluff 70, 30); Testing an Enemy's Strength (Thunder Bluff 70, 30).", zone="Orgrimmar", map=1454, x=52.6, y=49.0, dg=1, run=true},
