  {t="C", seg=7, q={95883}, names={"The Tortured Soul"}, text="Kill the undead in the cave until you loot a Tortured Soul", zone="Silverpine Forest", map=1421, x=59.3, y=71.7, path={{60.2,72.0}}, cave=true},
  {t="T", seg=7, q={95883}, names={"The Tortured Soul"}, text="Back at the Offering Stone", zone="Silverpine Forest", map=1421, x=58.0, y=69.8},
  {t="A", seg=7, q={95885}, names={"The Offering of Blood"}, text="OPTIONAL elite. Only if you are at full health and mana. Skip the next two steps if you do not want to fight it.", zone="Silverpine Forest", map=1421, x=58.0, y=69.8},
  {t="C", seg=7, q={95885}, names={"The Offering of Blood"}, text="Use the Tortured Soul at the stone. An elite ghost spawns; it is undead, so Polymorph does not work. Mana Shield, then Frost Nova and kite it with Frostbolt.", zone="Silverpine Forest", map=1421, x=59.4, y=72.2},
  {t="T", seg=7, q={95885}, names={"The Offering of Blood"}, zone="Silverpine Forest", map=1421, x=58.1, y=69.9},
  {t="C", seg=7, q={480}, names={"The Weaver"}, text="Walk north-east to Ambermill. Archmage Ataeric (level 22) is at 63.4, 64.3; a rare Dalaran Spellscribe may be standing next to him. Pull the guards around him first, then loot Ataeric's Staff.", zone="Silverpine Forest", map=1421, x=63.4, y=64.3},
  {t="C", seg=7, q={95981}, names={"Watching the Roads"}, text="Finish the 8 Dalaran Wizards and 8 Dalaran Watchers on the roads south and east of Ambermill, on your way out toward Hillsbrad", zone="Silverpine Forest", map=1421, x=61.3, y=76.8},
  {t="A", seg=7, q={494}, names={"Time To Strike"}, text="Take the road east out of Silverpine into Hillsbrad. Deathstalker Lesh camps beside the road.", zone="Hillsbrad Foothills", map=1424, x=20.8, y=47.4},
  {t="F", seg=7, arg="Tarren Mill", text="Run north-east to Tarren Mill and stay well clear of Southshore (Alliance town). Talk to Zarise for the flight path.", zone="Hillsbrad Foothills", map=1424, x=60.1, y=18.6},
  {t="T", seg=7, q={493,1065}, names={"Journey to Hillsbrad Foothills","Journey to Tarren Mill"}, text="Apothecary Lydon, a few steps east of Zarise", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=7, q={1066,496,501}, names={"Blood of Innocents","Elixir of Suffering","Elixir of Pain"}, text="Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=7, q={494}, names={"Time To Strike"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.5},
  {t="A", seg=7, q={527}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=7, q={549}, names={"WANTED: Syndicate Personnel"}, text="WANTED poster right next to Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.6, y=20.8},
  {t="A", seg=7, q={498}, names={"The Rescue"}, text="Krusk, a few steps further east", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="C", seg=7, q={498,549,1066}, names={"The Rescue","WANTED: Syndicate Personnel","Blood of Innocents"}, text="Durnholde Keep is south-east of Tarren Mill. Free Drull (75.3, 41.5) and Tog'thar (79.8, 39.7) by clicking their ball and chains. Kill Syndicate Rogues and Watchmen. Syndicate Shadow Mages drop the Vials of Innocent Blood.", zone="Hillsbrad Foothills", map=1424, x=77.5, y=40.5},
  {t="C", seg=7, q={496}, names={"Elixir of Suffering"}, text="Gray Bears drop the tongues and Forest Moss Creepers drop the ichor. Both roam the hills between Durnholde and Tarren Mill.", zone="Hillsbrad Foothills", map=1424, x=64.5, y=33.5},
  {t="T", seg=7, q={498}, names={"The Rescue"}, text="Krusk", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7, path={{63.2,31.6},{63.4,28.3},{66.0,25.6},{66.0,23.2}}},
  {t="T", seg=7, q={549}, names={"WANTED: Syndicate Personnel"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.5},
  {t="T", seg=7, q={1066}, names={"Blood of Innocents"}, text="Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=7, q={1067}, names={"Return to Thunder Bluff"}, text="Apothecary Lydon. Keep it for Thunder Bluff (next segment)", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=7, q={496}, names={"Elixir of Suffering"}, zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=7, q={499}, names={"Elixir of Suffering"}, zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=7, q={499}, names={"Elixir of Suffering"}, text="Umpi, standing next to Lydon", zone="Hillsbrad Foothills", map=1424, x=61.5, y=19.1},
  {t="FLY", seg=7, arg="The Sepulcher", text="From Zarise in Tarren Mill (the flight goes through the Undercity)"},
  {t="T", seg=7, q={516,95981,480}, names={"Beren's Peril","Watching the Roads","The Weaver"}, text="Shadow Priest Allister", zone="Silverpine Forest", map=1421, x=44.0, y=40.9},
  {t="A", seg=7, q={1098}, names={"Deathstalkers in Shadowfang"}, text="High Executor Hadrec at the Sepulcher. It ends inside the keep, at Deathstalker Vincent.", zone="Silverpine Forest", map=1421, x=43.4, y=40.9, dg=4},
  {t="T", seg=7, q={98299}, names={"Stop the Spread"}, text="Dalar Dawnweaver", zone="Silverpine Forest", map=1421, x=44.2, y=39.8},
  {t="A", seg=7, q={1014}, names={"Arugal Must Die"}, text="Dalar Dawnweaver at the Sepulcher. Kill Arugal, the last boss.", zone="Silverpine Forest", map=1421, x=44.2, y=39.8, dg=4},
  {t="N", seg=7, arg="Optional dungeon: Shadowfang Keep, levels 22-30", text="The keep is in the south of Silverpine, on the hill above Pyrewood Village: follow the road south from the Sepulcher. Hand Deathstalkers in Shadowfang in to Deathstalker Vincent inside. Quests you picked up for it: The Book of Ur, Deathstalkers in Shadowfang, Arugal Must Die.", zone="Silverpine Forest", map=1421, x=44.8, y=67.8, dg=4, run=true},
  {t="T", seg=7, q={1014}, names={"Arugal Must Die"}, zone="Silverpine Forest", map=1421, x=44.2, y=39.8, dg=4},
  {t="FLY", seg=7, arg="Undercity", text="Bat handler Karos Razok"},
  {t="T", seg=7, q={530}, names={"A Husband's Revenge"}, text="Raleigh Andrean in the Trade Quarter", zone="Undercity", map=1458, x=62.0, y=42.8},
  {t="T", seg=7, q={1013}, names={"The Book of Ur"}, zone="Undercity", map=1458, x=53.7, y=54.5, dg=4},
  {t="TRAIN", seg=7, text="Undercity Magic Quarter: learn your level 22 spells. If you still lack Teleport: Undercity or Teleport: Orgrimmar, learn them from Lexington Mortaim, the portal trainer (84.2, 15.6), and buy Runes of Teleportation from Hannah Akeley, the reagent seller next to him (82.8, 15.8). The next segment needs them."},
  {t="FLY", seg=7, arg="Tarren Mill", text="Bat handler Michael Garrett"},
  {t="C", seg=7, q={501}, names={"Elixir of Pain"}, text="Starving Mountain Lions (level 23-24) roam the hills west of Tarren Mill on the way to the fields", zone="Hillsbrad Foothills", map=1424, x=53.8, y=40.2},
  {t="C", seg=7, q={527}, names={"Battle of Hillsbrad"}, text="Hillsbrad Fields (around 33, 40): Farmhands and Farmers. Farmer Ray is at 33.2, 34.8 and Farmer Getz at 36.7, 39.4.", zone="Hillsbrad Foothills", map=1424, x=33.4, y=38.7},
  {t="T", seg=7, q={501}, names={"Elixir of Pain"}, text="Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=7, q={502}, names={"Elixir of Pain"}, zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=7, q={527}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=7, q={528}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=7, q={546}, names={"Souvenirs of Death"}, text="Deathguard Samsa. Skulls drop from every Hillsbrad human; you finish them in segment 9.", zone="Hillsbrad Foothills", map=1424, x=62.1, y=19.7},
  {t="A", seg=7, q={567}, names={"Dangerous!"}, text="Dangerous! poster near the inn. You finish it in segment 9.", zone="Hillsbrad Foothills", map=1424, x=62.6, y=19.7},
  {t="T", seg=7, q={502}, names={"Elixir of Pain"}, text="Feed the elixir to Stanley, the dog at Farmer Ray's farm at the north end of the fields. He turns hostile after drinking it; kill him or run.", zone="Hillsbrad Foothills", map=1424, x=32.7, y=35.3, path={{64.6,19.3},{66.0,22.9},{66.0,25.6},{63.4,28.3},{62.8,32.2},{60.0,31.3},{57.2,26.2},{45.8,26.2},{38.6,34.9},{35.0,34.9},{33.8,36.7}}},
  {t="C", seg=7, q={528,567,567}, obj={0,2,4}, names={"Battle of Hillsbrad","Dangerous!","Dangerous!"}, text="Kill 15 Hillsbrad Peasants in the fields. Citizen Wilkes (level 25) walks the north edge of the farms around 32.6, 39.8 (a Footman stands close by; pull them apart), and Farmer Kalaba (level 25) works the field at 35.9, 46.6. Kill both for Dangerous!. Leave Clerk Horrace for segment 9: he is in the town hall next to Magistrate Burnside (level 30).", zone="Hillsbrad Foothills", map=1424, x=33.4, y=44.5},
  {t="T", seg=7, q={528}, names={"Battle of Hillsbrad"}, text="Walk back to Tarren Mill: High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=7, q={529}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=7, q={98094}, names={"Scout Support"}, text="High Executor Darthalia (new in Forever). Keep it for the next Tarren Mill visit.", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="L", seg=7, lvl=23, text="Walk back to the fields. Quest XP runs short here: kill Farmers, Farmhands and Peasants (level 23-25) until level 23. Their skulls count toward Souvenirs of Death.", zone="Hillsbrad Foothills", map=1424, x=34.5, y=44.0},
  {t="C", seg=7, q={529}, names={"Battle of Hillsbrad"}, text="The smithy in the middle of the fields: kill 4 Hillsbrad Apprentice Blacksmiths first, then Blacksmith Verringtan (level 26) at full mana, alone: Frost Nova and kite him. The Shipment of Iron crate sits by the forge (32.0, 45.5). If Verringtan is too strong, leave the quest for segment 9, which comes back here.", zone="Hillsbrad Foothills", map=1424, x=32.0, y=45.0},
  {t="H", seg=7, arg="Crossroads", text="Your hearthstone is still set to the Crossroads. Keep Battle of Hillsbrad in your log; you hand it in on the next Tarren Mill visit."},
  {t="G", seg=8, text="Run west from the Crossroads along the road to the Stonetalon border, where Seereth Stonebreak stands. 1068 is not finished yet; you come back past him on the way to Ashenvale", zone="The Barrens", map=1413, x=35.3, y=27.9},
  {t="A", seg=8, q={1058}, names={"Jin'Zil's Forest Magic"}, text="Witch Doctor Jin'Zil is in the small cave at Malaka'jin, just past the border into Stonetalon. The parts come from Stonetalon Peak, which you visit soon", zone="Stonetalon Mountains", map=1442, x=74.5, y=97.9},
  {t="A", seg=8, q={1090}, names={"Gerenzo's Orders"}, text="Follow the road north into Windshear Crag. Piznik stands at a mine entrance on the east side of the logging camp", zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0, path={{74.1,59.6}}, cave=true},
  {t="C", seg=8, q={1090}, names={"Gerenzo's Orders"}, text="Piznik mines for about a minute. Stay next to him and kill the Venture Co. patrols that come at him, then talk to him for the ore", zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0, path={{74.1,59.6}}, cave=true},
  {t="T", seg=8, q={1090}, names={"Gerenzo's Orders"}, zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0},
  {t="A", seg=8, q={1092}, names={"Gerenzo's Orders"}, zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0},
  {t="C", seg=8, q={1068}, obj={1}, names={"Shredding Machines"}, text="XT:4 is a goblin shredder (level 23) working the north end of the logging area, by Cragpool Lake. Gerenzo (level 27) stands on the heights just north of it: leave him alone for now", zone="Stonetalon Mountains", map=1442, x=64.1, y=46.4},
  {t="C", seg=8, q={1068}, obj={2}, names={"Shredding Machines"}, text="XT:9, the second shredder (level 23), works the logging area further south", zone="Stonetalon Mountains", map=1442, x=64.1, y=56.6},
  {t="T", seg=8, q={1095,1092}, names={"Further Instructions","Gerenzo's Orders"}, text="Ziz Fizziks stands under the cliff at the south-west edge of Windshear Crag. He then offers Gerenzo Wrenchwhistle: do not take it yet. You come back for it after Ashenvale, about two levels higher, and leaving it keeps your log small there", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="G", seg=8, text="Walk west to Sun Rock Retreat and its wind rider master. Take the Sun Rock quests when you come back, not now", zone="Stonetalon Mountains", map=1442, x=45.1, y=59.8},
  {t="FLY", seg=8, arg="Thunder Bluff"},
  {t="T", seg=8, q={1067}, names={"Return to Thunder Bluff"}, text="Apothecary Zamah is in the Pools of Vision, in the caves under Spirit Rise", zone="Thunder Bluff", map=1456, x=22.8, y=20.9},
  {t="A", seg=8, q={1086}, names={"The Flying Machine Airport"}, text="Keep the Toxic Fogger. You use it at the goblins' sky port in Windshear Crag near the end of this segment, and hand the quest in to Zamah on a later Thunder Bluff visit", zone="Thunder Bluff", map=1456, x=22.8, y=20.9},
  {t="A", seg=8, q={97538}, names={"Pigments for Paints"}, text="New Forever quest. Tah Winterhoof stands on the central rise. The pods come from Mirkfallon Lake in Stonetalon. Keep the quest: you hand the pods in when you come back to Thunder Bluff early in the next segment (Tah is a few steps from Zangen Stonehoof)", zone="Thunder Bluff", map=1456, x=54.5, y=47.4},
  {t="N", seg=8, arg="Buy at least 3 Runes of Teleportation from a reagent vendor before you leave Thunder Bluff. The level 26 class quest uses three Teleports"},
  {t="FLY", seg=8, arg="Sun Rock Retreat"},
  {t="A", seg=8, q={6301}, names={"Cycle of Rebirth"}, text="Tammra Windfield, in the middle of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="A", seg=8, q={1087}, names={"Cenarius' Legacy"}, text="Braelyn Firehand, on the west side of Sun Rock Retreat. Leave the other Sun Rock quests (Charred Vale, mobs up to level 27) until you come back after Ashenvale", zone="Stonetalon Mountains", map=1442, x=45.9, y=60.4},
  {t="C", seg=8, q={6301,97538}, names={"Cycle of Rebirth","Pigments for Paints"}, text="Walk north to Mirkfallon Lake. Gaea Seeds lie on the ground around the lake shore. Mirkweed plants grow in the shallow water of the lake; loot 30 Mirkweed Pods from them", zone="Stonetalon Mountains", map=1442, x=48.8, y=40.7},
  {t="C", seg=8, q={1087,1058}, names={"Cenarius' Legacy","Jin'Zil's Forest Magic"}, text="Keep going north to Stonetalon Peak (mobs level 22-25). The Sons and Daughters of Cenarius and the Cenarion Botanists camp south of the Alliance outpost at the Peak (stay away from its guards). Sap Beasts (sap), Twilight Runner cats (whiskers), Antlered and Great Coursers (30 eyes, roughly two per deer) and the small Fey Dragons (one scale) all roam the Peak. You do not need the druids and dryads further west (level 25-27)", zone="Stonetalon Mountains", map=1442, x=36.3, y=13.0, path={{51.4,38.8},{51.4,36.1},{50.0,34.0},{50.0,30.4},{49.0,28.9},{45.6,28.6},{44.0,25.9},{43.2,15.1},{41.6,12.7},{38.8,12.7},{37.6,14.5},{36.4,14.5}}},
  {t="T", seg=8, q={6301}, names={"Cycle of Rebirth"}, text="Walk back south to Sun Rock Retreat. Finish any missing Gaea Seeds or Mirkweed Pods at the lake on the way. Tammra then offers New Life: take it when you come back", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="T", seg=8, q={1087}, names={"Cenarius' Legacy"}, text="Braelyn then offers Ordanus (level 29, up in the druid den on the Peak). Skip it", zone="Stonetalon Mountains", map=1442, x=45.9, y=60.4},
  {t="A", seg=8, q={6562}, names={"Trouble in the Deeps"}, text="Tsunaman at Sun Rock Retreat. It sends you to Je'neu Sancrea at Zoram'gar Outpost.", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2, dg=5},
  {t="T", seg=8, q={1058}, names={"Jin'Zil's Forest Magic"}, text="Walk east into Windshear Crag and follow the road south to Jin'Zil's cave at Malaka'jin", zone="Stonetalon Mountains", map=1442, x=74.5, y=97.9},
  {t="A", seg=8, q={6542}, names={"Report to Kadrak"}, text="Darn Talongrip, in the Malaka'jin camp beside Jin'Zil's cave. It sends you to Kadrak, who is on your way north", zone="Stonetalon Mountains", map=1442, x=73.2, y=94.9},
  {t="T", seg=8, q={1068}, names={"Shredding Machines"}, text="Seereth Stonebreak, just across the border in the Barrens", zone="The Barrens", map=1413, x=35.3, y=27.9},
  {t="G", seg=8, text="Run north-east across the Dry Hills to Mor'shan Rampart, the Horde gate at the north end of the Barrens", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="T", seg=8, q={6542}, names={"Report to Kadrak"}, text="Kadrak, on the Mor'shan watch tower", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="A", seg=8, q={6543}, names={"The Warsong Reports"}, text="Kadrak. Right-click the Bundle of Reports for three Warsong Reports. Three Warsong messengers in Ashenvale each take one: talk to each of them, accept his short quest and hand it straight back to get his update", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="A", seg=8, q={6544}, names={"Torek's Assault"}, text="Follow the road north into Ashenvale. Torek and his raiders wait just west of the road, south of Splintertree Post", zone="Ashenvale", map=1440, x=68.3, y=75.3},
  {t="C", seg=8, q={6544}, names={"Torek's Assault"}, text="Tell Torek you are ready; he charges west into Silverwing Outpost. At the end Duriel Moonfire and four elves jump you inside the building. They have low health: Frost Nova, then burn them down, and drink a potion if needed", zone="Ashenvale", map=1440, x=68.3, y=75.3},
  {t="A", seg=8, q={6503}, names={"Ashenvale Outrunners"}, text="Kuray'bin waits by the road a little further north", zone="Ashenvale", map=1440, x=71.1, y=68.1},
  {t="C", seg=8, q={6543}, obj={1}, names={"The Warsong Reports"}, text="The Warsong Scout stands next to Kuray'bin: give him the first report", zone="Ashenvale", map=1440, x=71.0, y=68.4},
  {t="C", seg=8, q={6503}, names={"Ashenvale Outrunners"}, text="Ashenvale Outrunners are stealthed night elf scouts in the woods on both sides of the road around Kuray'bin and Torek. Walk the slopes; they show themselves when they attack", zone="Ashenvale", map=1440, x=73.5, y=72.3},
  {t="T", seg=8, q={6503}, names={"Ashenvale Outrunners"}, zone="Ashenvale", map=1440, x=71.1, y=68.1},
  {t="F", seg=8, arg="Splintertree Post"},
  {t="S", seg=8, arg="Splintertree Post", text="Innkeeper Kaylisk. The class quest later uses this hearth"},
  {t="T", seg=8, q={6544}, names={"Torek's Assault"}, text="Ertog Ragetusk", zone="Ashenvale", map=1440, x=73.0, y=62.5},
  {t="T", seg=8, q={742}, names={"The Ashenvale Hunt"}, text="Senani Thunderheart", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="A", seg=8, q={6383}, names={"The Ashenvale Hunt"}, zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="T", seg=8, q={6383}, names={"The Ashenvale Hunt"}, text="This opens the Ashenvale Hunt. Sharptalon (level 31, south of the post) is for much later; skip him", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="A", seg=8, q={25}, names={"Stonetalon Standstill"}, text="Mastok Wrilehiss. Also skip: The Lost Pages (Gurda Ragescar, level 30, the pages are random drops) and Warsong Supplies (needs a crate from Booty Bay and an engineering gun)", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="C", seg=8, q={25}, names={"Stonetalon Standstill"}, text="Mystral Lake is south-west of Splintertree. Kill the Befouled Water Elementals around the lake and walk onto the gazebo on the lake (48.9, 69.6) to scout it. Keep away from Silverwind Refuge, the Alliance camp by the lake", zone="Ashenvale", map=1440, x=49.0, y=70.4},
  {t="A", seg=8, q={1918}, names={"The Befouled Element"}, text="Tideress (level 27) is a named water elemental near the small island in the west of the lake. Her Befouled Water Globe starts this quest", zone="Ashenvale", map=1440, x=45.9, y=70.6},
  {t="A", seg=8, q={23}, names={"Ursangous's Paw"}, text="Ursangous (level 25, a druid in bear form) patrols the woods west of Mystral Lake. His paw starts this quest. A huge elite treant also patrols here: keep your distance", zone="Ashenvale", map=1440, x=39.8, y=65.2, path={{46.2,67.2},{45.0,64.8},{43.2,64.8},{42.2,66.3}}},
  {t="A", seg=8, q={98251}, names={"Never Coming Back"}, text="New Forever quest. Va'xug Firefure, a lost warlock, sits in a ravine just north of Ursangous", zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="C", seg=8, q={98251}, names={"Never Coming Back"}, text="Shadowhorn Stags and Ashenvale Bears roam all around the ravine", zone="Ashenvale", map=1440, x=39.7, y=65.4},
  {t="T", seg=8, q={98251}, names={"Never Coming Back"}, zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="A", seg=8, q={98252}, names={"A Void Path"}, zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="C", seg=8, q={98252}, names={"A Void Path"}, text="Va'xug's Eye of Kilrogg follows you: lead it out of the ravine to the main road within four minutes. If the channel breaks, go back to her and try again", zone="Ashenvale", map=1440, x=38.6, y=58.3},
  {t="T", seg=8, q={98252}, names={"A Void Path"}, text="Hand it in to the Eye of Kilrogg itself, at the road", zone="Ashenvale", map=1440, x=38.6, y=58.3},
  {t="G", seg=8, text="Astranaar (Alliance town, level 40 guards) is straight north up this road, only a short way off. Do not follow the road: head due west first, keeping Astranaar well to your right", zone="Ashenvale", map=1440, x=30.0, y=57.0},
  {t="G", seg=8, text="Now turn north-west and cross the forest to Zoram'gar Outpost on the coast. Keep clear of the night elves at around 22, 53 (on your left) and of Maestra's Post (Alliance, around 27, 36, on your right)", zone="Ashenvale", map=1440, x=12.2, y=33.8},
  {t="F", seg=8, arg="Zoram'gar Outpost"},
  {t="C", seg=8, q={6543}, obj={2}, names={"The Warsong Reports"}, text="The Warsong Runner is in the outpost: give him the second report", zone="Ashenvale", map=1440, x=12.2, y=34.2},
  {t="A", seg=8, q={6442}, names={"Naga at the Zoram Strand"}, text="Marukai", zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="A", seg=8, q={6462}, names={"Troll Charm"}, text="Mitsuwa", zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="A", seg=8, q={216}, names={"Between a Rock and a Thistlefur"}, text="Karang Amakkar. Skip Vorsha the Lasher (Muglash) and King of the Foulweald: both are elite", zone="Ashenvale", map=1440, x=11.9, y=34.5},
  {t="C", seg=8, q={6442}, names={"Naga at the Zoram Strand"}, text="Wrathtail naga line the Zoram Strand north of the outpost. Every kind drops heads", zone="Ashenvale", map=1440, x=8.7, y=14.4},
  {t="T", seg=8, q={6442}, names={"Naga at the Zoram Strand"}, zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="T", seg=8, q={6562}, names={"Trouble in the Deeps"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5, req=6562},
  {t="A", seg=8, q={6563}, names={"The Essence of Aku'Mai"}, text="20 Sapphires of Aku'Mai: they grow on the walls of the tunnels before the dungeon portal.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5, req=6562},
  {t="A", seg=8, q={6921}, names={"Amongst the Ruins"}, text="Je'neu Sancrea. The Fathom Core is under water in the first big pool inside the dungeon.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="N", seg=8, arg="Optional dungeon: Blackfathom Deeps, levels 24-32", text="The entrance is on the coast north of Zoram'gar Outpost: go down through the ruins and the tunnels to the portal. On the way, the naga and satyrs can drop a Damp Note; hand it to Je'neu to get Allegiance to the Old Gods (kill Lorgus Jett inside). Inside: Argent Guard Thaelrid gives Blackfathom Villainy (the head of Twilight Lord Kelris). Quests you picked up for it: The Essence of Aku'Mai, Amongst the Ruins.", zone="Ashenvale", map=1440, x=14.5, y=14.2, dg=5, run=true},
  {t="T", seg=8, q={6563}, names={"The Essence of Aku'Mai"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="T", seg=8, q={6921}, names={"Amongst the Ruins"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="T", seg=8, q={6565}, names={"Allegiance to the Old Gods"}, text="Allegiance to the Old Gods, if you got it from the Damp Note.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="C", seg=8, q={216}, names={"Between a Rock and a Thistlefur"}, text="Thistlefur Village is inland, east of the Zoram Strand. Kill the Avengers and Shamans in and around the village", zone="Ashenvale", map=1440, x=36.0, y=36.3},
  {t="C", seg=8, q={6462}, names={"Troll Charm"}, text="Thistlefur Hold is the cave at the east end of the village. Troll Chests sit along its tunnels; each holds a Troll Charm", zone="Ashenvale", map=1440, x=40.7, y=33.6},
  {t="A", seg=8, q={6482}, names={"Freedom to Ruul"}, text="Ruul Snowhoof is a captive tauren deep inside Thistlefur Hold", zone="Ashenvale", map=1440, x=41.5, y=34.5},
  {t="C", seg=8, q={6482}, names={"Freedom to Ruul"}, text="Escort Ruul out of the cave. Furbolgs ambush you on the way; keep them off him. Afterwards you only need to talk to his sister in Splintertree. Keep 216 and 6462: you hand them in on a later flight back to Zoram'gar", zone="Ashenvale", map=1440, x=41.5, y=34.5},
  {t="A", seg=8, q={24}, names={"Shadumbra's Head"}, text="Run east-south-east across the middle of Ashenvale. Astranaar (around 36, 50) stays behind you to the south-west, and the worgen (level 29-32, around 50, 39) stay north of your path. Shadumbra (level 28 panther) patrols back and forth just south of Raynewood Retreat; her head starts this quest. Do not go up into Raynewood Retreat (around 62, 51): its guards are elites. Level 40 night elf sentinels guard a moonwell just south-east of her (59, 59): do not pull her toward it", zone="Ashenvale", map=1440, x=57.5, y=56.0},
  {t="T", seg=8, q={6482}, names={"Freedom to Ruul"}, text="Continue east to Splintertree Post. Yama Snowhoof", zone="Ashenvale", map=1440, x=74.1, y=60.9},
  {t="T", seg=8, q={23,24}, names={"Ursangous's Paw","Shadumbra's Head"}, text="Senani Thunderheart", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="T", seg=8, q={25,1918}, names={"Stonetalon Standstill","The Befouled Element"}, text="Mastok Wrilehiss", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="A", seg=8, q={824}, names={"Je'neu of the Earthen Ring"}, text="The globe goes to Je'neu at Zoram'gar; you fly there before going back to Sun Rock", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="A", seg=8, q={6441}, names={"Satyr Horns"}, text="Pixel", zone="Ashenvale", map=1440, x=73.1, y=61.5},
  {t="C", seg=8, q={6441}, names={"Satyr Horns"}, text="Night Run is the satyr valley just north-west of Splintertree. Every Felmusk satyr (level 25-27) can drop horns", zone="Ashenvale", map=1440, x=67.5, y=54.5},
  {t="T", seg=8, q={6441}, names={"Satyr Horns"}, text="Pixel", zone="Ashenvale", map=1440, x=73.1, y=61.5},
  {t="FLY", seg=8, arg="Zoram'gar Outpost"},
  {t="T", seg=8, q={824,216,6462}, names={"Je'neu of the Earthen Ring","Between a Rock and a Thistlefur","Troll Charm"}, text="Je'neu Sancrea, Karang Amakkar and Mitsuwa, all in the outpost", zone="Ashenvale", map=1440, x=11.6, y=34.3},
  {t="FLY", seg=8, arg="Sun Rock Retreat", text="A long flight with stops on the way"},
  {t="A", seg=8, q={6381}, names={"New Life"}, text="Tammra Windfield, in the middle of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="A", seg=8, q={6282,86576}, names={"Harpies Threaten","Bloodfury Trinkets"}, text="Maggran Earthbinder gives both. 86576 Bloodfury Trinkets is new in Forever; its sunstones go to Mor'rogal, who stands next to Tsunaman", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="A", seg=8, q={6393}, names={"Elemental War"}, text="Tsunaman, on the hill at the south end of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2},
  {t="C", seg=8, q={6381,6282,86576,6393}, names={"New Life","Harpies Threaten","Bloodfury Trinkets","Elemental War"}, text="The Charred Vale is the burnt valley west and south-west of Sun Rock. Plant the seeds in the Gaea Dirt Mounds on the valley floor. Kill all four kinds of Bloodfury harpy: Harpies and Ambushers (level 23-24), Slayers and Roguefeathers (25-26); Glittering Sunstones drop from them. Storm Witches (26-27) hit hard, so pull them one at a time. Incendrites drop from the fire elementals: Rogue Flame Spirits (23-24) on the way in, Burning Ravagers (24-25) and Burning Destroyers (26-27) deeper in the vale; Frost Nova and step back from the Destroyers. Leave Bloodfury Ripper (elite) alone", zone="Stonetalon Mountains", map=1442, x=33.1, y=68.0},
  {t="T", seg=8, q={6393}, names={"Elemental War"}, text="Back to Sun Rock: Tsunaman, on the south hill", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2},
  {t="T", seg=8, q={86576}, names={"Bloodfury Trinkets"}, text="Mor'rogal, next to Tsunaman", zone="Stonetalon Mountains", map=1442, x=47.2, y=64.0},
  {t="T", seg=8, q={6282}, names={"Harpies Threaten"}, text="Maggran then offers Bloodfury Bloodline (elite). Skip it", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="A", seg=8, q={5881}, names={"Calling in the Reserves"}, text="Maggran's letter goes to Grish Longrunner at the Great Lift in the next segment. Keep it", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="T", seg=8, q={6381}, names={"New Life"}, text="Tammra Windfield", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="A", seg=8, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Walk east to Ziz Fizziks, under the cliff at the south-west edge of Windshear Crag", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="C", seg=8, q={1086}, names={"The Flying Machine Airport"}, text="Walk north through Windshear Crag. The sky port is the goblins' landing pad with a parked flying machine, just east of where XT:4 worked: use the Toxic Fogger there, then leave", zone="Stonetalon Mountains", map=1442, x=66.5, y=45.5},
  {t="C", seg=8, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Gerenzo Wrenchwhistle (level 27) watches the site from high above Cragpool Lake, a little north-west of the pad, next to the big water wheel; follow the path up. Expect to be about level 25, two below him: pull him alone at full mana, open with Frostbolt, Frost Nova when he closes in, step back and keep casting. Loot his Mechanical Arm", zone="Stonetalon Mountains", map=1442, x=64.5, y=40.2},
  {t="T", seg=8, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Back south to Ziz Fizziks", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="L", seg=8, lvl=26, text="Quest XP runs out here. Walk back west past Sun Rock to the south end of the Charred Vale and kill the Bloodfury Slayers, Roguefeathers and Storm Witches and the basilisks there (level 25-28) until level 26. The class quest needs 26", zone="Stonetalon Mountains", map=1442, x=32.0, y=69.0, path={{57.0,62.4},{55.2,59.7},{52.6,59.7},{51.0,61.8},{48.0,62.7},{45.4,66.9},{43.4,66.9},{38.0,72.6},{32.4,71.1}}},
  {t="N", seg=8, arg="Teleport: Undercity (uses a Rune of Teleportation). Without the spell, walk to Sun Rock, fly to Orgrimmar and take the zeppelin to Tirisfal Glades instead"},
  {t="A", seg=8, q={1943}, names={"Speak with Deino"}, text="Anastasia Hartwell in the Magic Quarter", zone="Undercity", map=1458, x=85.1, y=10.0},
