  {t="N", seg=8, arg="Teleport: Orgrimmar (or take the zeppelin from the tower outside Undercity if you don't have it)"},
  {t="T", seg=8, q={1943}, names={"Speak with Deino"}, text="Deino, in the Valley of Spirits", zone="Orgrimmar", map=1454, x=38.5, y=86.1},
