  {t="T", seg=8, q={3923}, names={"Rilli Greasygob"}, text="Rilli Greasygob, in the Valley of Honor. Skip her next quest, Samophlange Manual: its parts drop from low-level goblins in the northern Barrens", zone="Orgrimmar", map=1454, x=76.5, y=24.4},
  {t="H", seg=8, arg="Splintertree Post"},
  {t="C", seg=8, q={6543}, obj={3}, names={"The Warsong Reports"}, text="The Warsong Outrider waits on the road east of Splintertree, toward Azshara: give him the last report. Xavian is north-west of him", zone="Ashenvale", map=1440, x=81.8, y=53.5},
  {t="C", seg=8, q={1944}, names={"Waters of Xavian"}, text="Xavian is the satyr ruin north of Splintertree. Use Deino's Flask at the bottom of the highest waterfall, on the west side of the ruins. The satyrs here are level 27-30: pull one at a time or slip past them", zone="Ashenvale", map=1440, x=76.3, y=41.5},
  {t="N", seg=8, arg="Teleport: Orgrimmar (or fly from Splintertree Post to Orgrimmar if you don't have it)"},
  {t="T", seg=8, q={1944}, names={"Waters of Xavian"}, text="Deino", zone="Orgrimmar", map=1454, x=38.5, y=86.1},
  {t="A", seg=8, q={1945}, names={"Laughing Sisters"}, text="Deino", zone="Orgrimmar", map=1454, x=38.5, y=86.1},
  {t="FLY", seg=8, arg="Splintertree Post"},
  {t="C", seg=8, q={1945}, names={"Laughing Sisters"}, text="Laughing Sisters are the dryads in the woods below Raynewood Retreat, west of Splintertree. Kill them for 12 hairs, and loot one Etched Phial (for 1195) from them too. Stay out of Raynewood Retreat itself and away from the guarded moonwell at 59, 59", zone="Ashenvale", map=1440, x=59.9, y=54.4},
  {t="C", seg=8, q={1195}, names={"The Sacred Flame"}, text="Use the Etched Phial at the moonwell on the west bank of the Falfarren River, south of the main road. Keep the Filled Etched Phial for Thunder Bluff in the next segment", zone="Ashenvale", map=1440, x=60.2, y=72.9, path={{59.6,56.7},{56.4,58.2},{56.4,62.7},{58.6,66.3},{58.8,69.9}}},
  {t="G", seg=8, text="Walk east to the Horde road at the Splintertree guard post, passing north of Silverwing Outpost", zone="Ashenvale", map=1440, x=69.7, y=71.7},
  {t="T", seg=8, q={6543}, names={"The Warsong Reports"}, text="Kadrak. Follow the road south out of Ashenvale to Mor'shan Rampart", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="T", seg=8, q={1945}, names={"Laughing Sisters"}, text="Kil'hala, the tailor at the Crossroads. Keep following the road south from Mor'shan to the Crossroads", zone="The Barrens", map=1413, x=52.2, y=31.7, path={{47.4,12.1},{44.2,17.2},{43.8,25.0},{46.2,29.8}}},
