  {t="T", seg=9, q={874}, names={"Mahren Skyseer"}, text="Mahren Skyseer stands on the shore a short run south of Ratchet", zone="The Barrens", map=1413, x=65.8, y=43.9},
  {t="A", seg=9, q={873}, names={"Isha Awak"}, zone="The Barrens", map=1413, x=65.8, y=43.9},
  {t="C", seg=9, q={873}, names={"Isha Awak"}, text="Isha Awak is a big threshadon (level 27) swimming off this coast to the south, around 63,54. Pull it toward the shallows and fight it there", zone="The Barrens", map=1413, x=63.5, y=53.9},
  {t="T", seg=9, q={873}, names={"Isha Awak"}, zone="The Barrens", map=1413, x=65.8, y=43.9},
  {t="A", seg=9, q={1221}, names={"Blueleaf Tubers"}, text="Mebok Mizzyrix in Ratchet. Take the crate, the command stick and the manual next to him. In the kraul, let the gopher out near the blueleaf trail and use the stick to make it dig up 6 tubers.", zone="The Barrens", map=1413, x=62.4, y=37.6, dg=8},
  {t="FLY", seg=9, arg="Thunder Bluff", text="The flight routes through the Crossroads"},
  {t="T", seg=9, q={1195}, names={"The Sacred Flame"}, text="Zangen Stonehoof, on the central mesa of Thunder Bluff", zone="Thunder Bluff", map=1456, x=55.0, y=51.4},
  {t="T", seg=9, q={97538}, names={"Pigments for Paints"}, text="Tah Winterhoof, a few steps from Zangen on the same central rise. Hand in the 30 Mirkweed Pods from Mirkfallon Lake", zone="Thunder Bluff", map=1456, x=53.9, y=47.3},
  {t="T", seg=9, q={6561}, names={"Blackfathom Villainy"}, text="Blackfathom Villainy: Bashana Runetotem on Elder Rise.", zone="Thunder Bluff", map=1456, x=71.1, y=34.2, dg=5},
  {t="A", seg=9, q={1196}, names={"The Sacred Flame"}, text="Keep the Filled Etched Phial for Freewind Post. Leave 1086 and 1130 in your log for later", zone="Thunder Bluff", map=1456, x=55.0, y=51.4},
