  {t="A", seg=9, q={879}, names={"Betrayal from Within"}, text="Mangletooth, the quilboar in the cage", zone="The Barrens", map=1413, x=44.5, y=59.3},
  {t="A", seg=9, q={884}, names={"Owatanka"}, text="Optional: Owatanka, a named thunderhawk, flies around Camp Taurajo. Its Tailspike starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=47.0, y=61.0},
  {t="A", seg=9, q={883}, names={"Lakota'mani"}, text="Optional: Lakota'mani, a named grey kodo, wanders just north of Camp Taurajo. Its Hoof starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=47.2, y=51.6, path={{48.6,60.6},{48.8,57.6},{48.8,54.9}}},
  {t="C", seg=9, q={868}, names={"Egg Hunt"}, text="Field of Giants south of Camp Taurajo: loot eggs from the Silithid Mounds and kill the silithid around them", zone="The Barrens", map=1413, x=45.2, y=70.8, path={{48.8,54.6},{48.6,66.3},{47.4,72.0},{45.2,72.0}}},
  {t="A", seg=9, q={98093}, names={"Field to Clear"}, text="Sulhasa is stuck up a tree beside the road south of the silithid field, with lizards and hyenas all around her", zone="The Barrens", map=1413, x=47.9, y=77.6, path={{44.8,78.0}}},
  {t="A", seg=9, q={885}, names={"Washte Pawne"}, text="Optional: Washte Pawne, a named wind serpent, flies over the Field of Giants. Its Feather starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=44.8, y=78.9},
