  {t="C", seg=9, q={843}, names={"Gann's Reclamation"}, text="Bael Modan dig site: kill Bael'dun Excavators and Foremen. Prospector Khazgorm in the pit drops the journal. Kill Stormhide and Hecklefang Stalkers for Field to Clear on every trip", zone="The Barrens", map=1413, x=47.6, y=85.2},
  {t="T", seg=9, q={843}, names={"Gann's Reclamation"}, zone="The Barrens", map=1413, x=45.9, y=77.0},
