  {t="A", seg=9, q={857}, names={"The Tear of the Moons"}, text="Feegly the Exiled, at the east edge of Bael Modan", zone="The Barrens", map=1413, x=49.0, y=86.3},
  {t="C", seg=9, q={846,857}, names={"Revenge of Gann","The Tear of the Moons"}, text="Bael'dun Keep: soldiers, riflemen and officers drop the Nitroglycerin, Wood Pulp and Sodium Nitrate. The Tear of the Moons is in General Twinbraid's Strongbox inside the keep (49.1,84.2). General Twinbraid himself (level 30) stands right beside it: clear the soldiers around him first, then Polymorph him, loot the box and walk away (or kill him at full mana with Frost Nova + Frostbolt)", zone="The Barrens", map=1413, x=49.1, y=84.2},
  {t="T", seg=9, q={857}, names={"The Tear of the Moons"}, zone="The Barrens", map=1413, x=49.0, y=86.3},
