  {t="C", seg=9, q={893,879}, names={"Weapons of Choice","Betrayal from Within"}, text="Blackthorn Ridge, west of Gann: Razormane Pathfinders/Stalkers drop the Backstabber, Seers the Wand, Warfrenzy the Shield. Kuz is at 45,80, Nak at 44,83, Lok Orcbane at 40,80", zone="The Barrens", map=1413, x=42.8, y=81.3},
  {t="C", seg=9, q={98093}, names={"Field to Clear"}, text="Finish the 7 Stormhide and 7 Hecklefang Stalkers if you still need them", zone="The Barrens", map=1413, x=46.4, y=77.5},
