  {t="C", seg=10, q={1147,1148}, names={"The Swarm Grows","Parts of the Swarm"}, text="Same hive: 5 Searchers, 5 Hive Drones, 5 Invaders, plus 1 Heart, 5 Talons and 3 Intact Carapaces from any of them. Searchers (32-33) are on the north side, Drones (33-34) in the middle, Invaders (34-35) on the west edge (64,86). Pull one at a time", zone="Thousand Needles", map=1441, x=69.5, y=85.2},
  {t="T", seg=10, q={1147}, names={"The Swarm Grows"}, text="Back north to Moktar Krin", zone="Thousand Needles", map=1441, x=67.6, y=63.9},
