  {t="N", seg=10, arg="Optional dungeon: Razorfen Kraul, levels 29-38", text="The entrance is in the far south-west of the Barrens, south of Camp Taurajo, where the road turns towards the Great Lift. Inside: Willix the Importer, near the end, gives an escort quest that also ends with him. Quests you picked up for it: Blueleaf Tubers, A Vengeful Fate. Not on your path, only if you want the detour: Going, Going, Guano! (Undercity 49, 69).", zone="The Barrens", map=1413, x=42.9, y=90.2, dg=8, run=true},
