  {t="N", seg=10, arg="Optional dungeon: Gnomeregan, levels 29-38", text="For the Horde the way in is the teleporter pad next to Scooty in Booty Bay (you need his Goblin Transponder). It drops you inside Gnomeregan, close to the dungeon portal. Inside: Kernobee gives an escort quest, A Fine Mess, that ends at Scooty. Quests you picked up for it: Rig Wars.", zone="Stranglethorn Vale", map=1434, x=27.6, y=77.5, dg=9, run=true},
  {t="T", seg=10, q={2904}, names={"A Fine Mess"}, text="A Fine Mess, if you escorted Kernobee.", zone="Stranglethorn Vale", map=1434, x=27.6, y=77.5, dg=9},
  {t="N", seg=10, arg="Teleport: Orgrimmar", text="No rune or spell? Run north along the main road from Booty Bay to Grom'gol instead (about 6 minutes) and keep 1184 for the next Orgrimmar visit"},
