  {t="A", seg=10, q={95697}, names={"Changing Tastes"}, text="Borstan at his firepit in the Drag. 4 Thicket Raptor Meat from the raptors inside the dungeon.", zone="Orgrimmar", map=1454, x=57.4, y=53.4, dg=6},
