  {t="N", seg=10, arg="Optional new quests at the Ruins of Zul'Kunda (24,10), just north of the raptors: zeppelin crash debris and a caged goblin, Zimmix Sputterspark, start NEW level 35 quests that end in Booty Bay. Take them only if the 34-37 trolls there are manageable; the logger records them", text="The Bloodscalps there also drop the ears, tusks and necklaces you need next"},
  {t="T", seg=10, q={186}, names={"Tiger Mastery"}, text="Back east to Ajeck Rouack at Nesingwary's camp. Don't take the next tier yet; you get it on the next Stranglethorn visit", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="T", seg=10, q={191}, names={"Panther Mastery"}, text="Sir S. J. Erlgadin. Don't take the next tier yet; you get it on the next Stranglethorn visit", zone="Stranglethorn Vale", map=1434, x=35.5, y=10.6},
  {t="T", seg=10, q={194}, names={"Raptor Mastery"}, text="Hemet Nesingwary. Don't take the next tier yet; you get it on the next Stranglethorn visit", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="C", seg=10, q={581,596,189}, names={"Hunt for Yenniku","Bloody Bone Necklaces","Bloodscalp Ears"}, text="Head south toward Grom'gol through the Bloodscalp camps: first 33-34,14-17 just south-west of the hunters' camp, then 29-30,19-20. Any Bloodscalp can drop ears, tusks and necklaces. They are 33-34: pull one at a time and kill axe throwers and shamans first", zone="Stranglethorn Vale", map=1434, x=33.5, y=15.5},
  {t="L", seg=10, lvl=31, text="Drizzlik's next quest in Booty Bay needs 31. If you are short, keep killing Bloodscalps at the Bal'lal camps (29-30,19-20 and 33-34,15), TUGs' Classic Stranglethorn grind spot, before going on to Grom'gol", zone="Stranglethorn Vale", map=1434, x=29.8, y=19.5},
  {t="T", seg=10, q={581}, names={"Hunt for Yenniku"}, text="Nimboya, Grom'gol", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.7},
