  {t="A", seg=10, q={213}, names={"Hostile Takeover"}, text="Kebok: Hostile Takeover (needs level 31). Do not go now: the Venture Co. geologists are 34-36 and the route is at their camp in segment 13. Not offered because you are 30? Press Skip: the later steps for it then pass by themselves", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.1},
