  {t="N", seg=11, arg="Open Elixir of Agony (515) in your quest log and buy the exact troll's blood potion it lists at the Auction House", text="Forever's quest page lists a Lesser Troll's Blood Elixir, while the old quest text says Strong Troll's Blood Potion: buy whichever your log shows. If none is for sale, skip the two Hillsbrad coast steps later and abandon 515."},
  {t="A", seg=11, q={1164}, names={"To Steal From Thieves"}, text="Genavie Callow, near the west elevator by the bat handler. The Dabyrie heads come from Arathi; you hand them in on a quick Undercity stop near the end of this segment.", zone="Undercity", map=1458, x=63.8, y=49.5},
  {t="FLY", seg=11, arg="Tarren Mill", text="Bat handler Michael Garrett, next to the west elevator"},
  {t="S", seg=11, arg="Tarren Mill", text="Bind at the Tarren Mill inn. You hearth back here after the coast run."},
