  {t="A", seg=11, q={544}, names={"Prison Break In"}, text="Magus Wordeen Voidglare", zone="Hillsbrad Foothills", map=1424, x=61.6, y=20.9},
  {t="A", seg=11, q={93680}, names={"Key to the City"}, text="Magus Wordeen Voidglare (new in Forever). Ignore his later Blood in the Streets: it leads into the City of Dalaran instance.", zone="Hillsbrad Foothills", map=1424, x=61.6, y=20.9},
  {t="A", seg=11, q={552}, names={"Helcular's Revenge"}, text="Novice Thaivand", zone="Hillsbrad Foothills", map=1424, x=63.9, y=19.7},
  {t="A", seg=11, q={533}, names={"Infiltration"}, text="Krusk. Leave his Regthar Deathgate for your last visit here. Tallow's Hammer May Fall also waits until you come back from the coast.", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="C", seg=11, q={533}, names={"Infiltration"}, text="The Syndicate camp just north of Tarren Mill. Kill Syndicate Footpads and Thieves until a Syndicate Missive drops. Skip Henchman Valik: his quest needs Southshore Stout from the Alliance town. If a Singed Note drops, keep it in your bags: it starts Strahnbrad Mystery, which you do at the end of this segment.", zone="Alterac Mountains", map=1416, x=58.3, y=68.0},
  {t="C", seg=11, q={552}, names={"Helcular's Revenge"}, text="Head south-west to the yeti cave in the hills west of Tarren Mill. Kill Cave and Ferocious Yetis until Helcular's Rod drops.", zone="Hillsbrad Foothills", map=1424, x=44.5, y=30.0, path={{46.3,31.6}}, cave=true},
  {t="C", seg=11, q={544,556,93680}, names={"Prison Break In","Stone Tokens","Key to the City"}, text="Go west to the Lordamere Internment Camp, south of the Dalaran dome. Kill Ricter, Alina, Dermot and Kegan Darkmar for the four Bloodstone pieces. Every Dalaran mob here drops Worn Stone Tokens. Search the camp for the Grimy Key (new quest, no map data yet). Polymorph the extra casters.", zone="Alterac Mountains", map=1416, x=19.5, y=84.5},
  {t="T", seg=11, q={533}, names={"Infiltration"}, text="Krusk. He offers Gol'dir (503) next: leave it until you come back from Arathi, when you do Strahnbrad.", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="T", seg=11, q={544}, names={"Prison Break In"}, text="Magus Wordeen Voidglare", zone="Hillsbrad Foothills", map=1424, x=61.6, y=20.9},
