  {t="C", seg=11, q={553}, obj={3}, names={"Helcular's Revenge"}, text="Go north to the yeti cave in Alterac and click the Flame of Uzel. Giant Yetis guard it.", zone="Alterac Mountains", map=1416, x=37.5, y=66.2},
