  {t="C", seg=12, q={93225}, names={"Carved Centaur Totems"}, text="Fewer than 5 totems? Kill Maraudine Scouts and Wranglers (36-38) on the south-east edge of the Valley of Spears, on the way from Ghost Walker Post to Gelkis Village. Pull them one at a time. If they are too strong, abandon 93225 and skip its hand-in later.", zone="Desolace", map=1443, x=36.5, y=65.5},
