  {t="C", seg=12, q={6161}, obj={1}, names={"Claim Rackmore's Treasure!"}, text="Kill Drysnap crabs around the wreck until Rackmore's Silver Key drops. They also drop Soft-shelled Clam Meat.", zone="Desolace", map=1443, x=33.0, y=32.0},
  {t="A", seg=12, q={5741}, names={"Sceptre of Light"}, text="Azore Aldamort, at the top of the tower at Ethel Rethor, just northeast of the wreck", zone="Desolace", map=1443, x=38.9, y=27.2},
  {t="C", seg=12, q={6143,6142,6161}, obj={0,0,2}, names={"Other Fish to Fry","Clam Bait","Claim Rackmore's Treasure!"}, text="Slitherblade naga on the shore north of Ethel Rethor, from about 36,28 up to 31,15: 7 Myrmidons, 7 Naga and 5 Sorceresses. Any naga can drop Rackmore's Golden Key and clam meat. Stay on the mainland; Ranazjar Isle comes later. Frost Nova and step back; the casters hit hard.", zone="Desolace", map=1443, x=35.0, y=22.0},
  {t="C", seg=12, q={5741}, names={"Sceptre of Light"}, text="Burning Blade Seer at the top of the tower in Thunder Axe Fortress. He has the Sceptre of Light.", zone="Desolace", map=1443, x=55.2, y=30.1, path={{39.0,31.9},{45.2,31.3},{47.4,34.0},{55.0,34.0}}},
  {t="C", seg=12, q={5381}, names={"Hand of Iruxos"}, text="Use the Demon Pick on the red Hand of Iruxos Crystal inside Thunder Axe Fortress. Kill the Demon Spirit (37) that appears and loot the Demon Box.", zone="Desolace", map=1443, x=55.0, y=26.7},
  {t="C", seg=12, q={1434,1481,97265}, names={"Befouled by Satyr","The Corrupter","Hate the Hatefury"}, text="Sargeron, the satyr camp in the northeast: 7 each of Hatefury Rogues, Felsworn, Betrayers and Hellcallers, plus 2 each of Tricksters, Hellcallers, Shadowstalkers, Felsworn and Rogues for Aka'rai. Shadowstalkers are stealthed; one drops the Shadowstalker Scalp.", zone="Desolace", map=1443, x=75.5, y=19.5},
