  {t="N", seg=13, arg="Take any new quests offered in Grom'gol; the logger records them", text="Forever adds new quests here (one is a naga quest for the coast west of the camp). Take them only if they are at your level and you have log room."},
  {t="T", seg=13, q={5763}, names={"Hunting in Stranglethorn"}, text="Hemet Nesingwary. Follow the road north from Grom'gol to the hunters' camp.", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="A", seg=13, q={187}, names={"Tiger Mastery"}, text="Ajeck Rouack", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="A", seg=13, q={192}, names={"Panther Mastery"}, text="Sir S. J. Erlgadin", zone="Stranglethorn Vale", map=1434, x=35.5, y=10.6},
  {t="A", seg=13, q={195}, names={"Raptor Mastery"}, text="Hemet Nesingwary", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="C", seg=13, q={187}, names={"Tiger Mastery"}, text="Elder Stranglethorn Tigers on the slopes just south of the camp", zone="Stranglethorn Vale", map=1434, x=34.0, y=18.5},
  {t="T", seg=13, q={187}, names={"Tiger Mastery"}, text="Ajeck Rouack", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="A", seg=13, q={188}, names={"Tiger Mastery"}, text="Ajeck Rouack", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="C", seg=13, q={188}, names={"Tiger Mastery"}, text="Sin'Dall, a named tigress (37) on the hill south-west of the camp", zone="Stranglethorn Vale", map=1434, x=32.2, y=17.4, path={{31.2,15.4},{31.2,17.2}}},
  {t="C", seg=13, q={568,195}, names={"The Defense of Grom'gol","Raptor Mastery"}, text="Lashtail Raptors in the jungle south of Sin'Dall's hill, between the camp and Grom'gol. 15 for Aggro'gosh, 10 for Hemet: the same kills count for both.", zone="Stranglethorn Vale", map=1434, x=35.0, y=23.0},
  {t="C", seg=13, q={577}, names={"Some Assembly Required"}, text="Snapjaw Crocolisks in and around Lake Nazferiti, east of the raptors", zone="Stranglethorn Vale", map=1434, x=40.0, y=22.0},
  {t="C", seg=13, q={1182}, names={"Goblin Sponsorship"}, text="Kill Foreman Cozzle at the Venture Co. camp on the lake's north-east shore for his key, then open Cozzle's Footlocker in his house (43.3, 20.3)", zone="Stranglethorn Vale", map=1434, x=42.6, y=18.4},
  {t="C", seg=13, q={213}, names={"Hostile Takeover"}, text="Hostile Takeover: the Venture Co. Geologists (34-36) in the same camp and along the north shore of the lake carry Tumbled Crystals, about one in two. You need 8", zone="Stranglethorn Vale", map=1434, x=42.6, y=18.4},
  {t="C", seg=13, q={192,570}, names={"Panther Mastery","Mok'thardin's Enchantment"}, text="Shadowmaw Panthers and Stranglethorn Tigresses in the jungle south-east of the lake. The panthers drop the claws, a tigress drops the fang. Both are 37-38: pull one at a time.", zone="Stranglethorn Vale", map=1434, x=44.0, y=28.0},
  {t="T", seg=13, q={188}, names={"Tiger Mastery"}, text="Back north to Ajeck Rouack at Nesingwary's camp", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6, path={{45.2,27.7},{45.8,22.9},{45.2,17.2},{41.4,11.5},{37.6,14.8}}},
  {t="T", seg=13, q={192}, names={"Panther Mastery"}, text="Sir S. J. Erlgadin. Skip the next part (Bhag'thera, elite).", zone="Stranglethorn Vale", map=1434, x=35.5, y=10.6},
  {t="T", seg=13, q={195}, names={"Raptor Mastery"}, text="Hemet. Leave the next part (Jungle Stalkers, level 41) for later.", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="N", seg=13, arg="Ruins of Zul'Kunda: Forever adds quests here (crash debris east of the ruins, and a caged goblin, Zimmix Sputterspark, inside). Take them if offered and do them with the headhunters; they turn in at Booty Bay. The logger records them."},
  {t="C", seg=13, q={582}, names={"Headhunting"}, text="Bloodscalp Headhunters around the Ruins of Zul'Kunda, west of Nesingwary's camp near the coast, drop the heads", zone="Stranglethorn Vale", map=1434, x=23.0, y=10.0, path={{33.8,11.8},{28.0,9.1}}},
  {t="T", seg=13, q={568}, names={"The Defense of Grom'gol"}, text="Commander Aggro'gosh, back south in Grom'gol", zone="Stranglethorn Vale", map=1434, x=32.2, y=28.9},
  {t="A", seg=13, q={569}, names={"The Defense of Grom'gol"}, zone="Stranglethorn Vale", map=1434, x=32.2, y=28.9},
  {t="T", seg=13, q={570}, names={"Mok'thardin's Enchantment"}, text="Far Seer Mok'thardin. Don't take the next part yet (level 41).", zone="Stranglethorn Vale", map=1434, x=32.1, y=29.2},
  {t="T", seg=13, q={582}, names={"Headhunting"}, text="Nimboya", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.7},
  {t="A", seg=13, q={584}, names={"Bloodscalp Clan Heads"}, text="Keep it for later (named troll bosses, level 40+)", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.7},
  {t="C", seg=13, q={569}, names={"The Defense of Grom'gol"}, text="Mosh'Ogg Brutes and Witch Doctors at the small ogre camp just east of Grom'gol", zone="Stranglethorn Vale", map=1434, x=37.0, y=31.0},
  {t="T", seg=13, q={569}, names={"The Defense of Grom'gol"}, text="Commander Aggro'gosh", zone="Stranglethorn Vale", map=1434, x=32.2, y=28.9},
  {t="FLY", seg=13, arg="Booty Bay"},
  {t="T", seg=13, q={1182}, names={"Goblin Sponsorship"}, text="Baron Revilgaz, top floor of the inn", zone="Stranglethorn Vale", map=1434, x=27.2, y=76.9},
  {t="T", seg=13, q={213}, names={"Hostile Takeover"}, text="Kebok, in the inn downstairs: the 8 Tumbled Crystals", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.1},
  {t="A", seg=13, q={1183}, names={"Goblin Sponsorship"}, text="Keep the blueprints for Pozzik on the Shimmering Flats", zone="Stranglethorn Vale", map=1434, x=27.2, y=76.9},
  {t="T", seg=13, q={577}, names={"Some Assembly Required"}, text="Drizzlik. Skip Excelsior (elite crocolisk).", zone="Stranglethorn Vale", map=1434, x=28.3, y=77.6},
  {t="T", seg=13, q={1115}, names={"The Rumormonger"}, text="Krazek", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2},
  {t="A", seg=13, q={1116}, names={"Dream Dust in the Swamp"}, text="Keep it for the Swamp of Sorrows", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2},
  {t="N", seg=13, arg="Optional dungeon: The Drowned City, levels 35-40", text="New Forever dungeon, not checked in game yet. It is on Gillijim's Isle, in the sea south-west of Stranglethorn Vale; the portal is in a cave called Sunken Hollow, and no boat or flight path was known to go there. Horde quests for it are listed from Krazek in Booty Bay (Shady Saltseers, The Saltseer Captain), Commander Aggro'gosh and Kin'weelay in Grom'gol, and Mazu'kon in Mulgore. Take what they offer: the addon logs it so these steps can be filled in.", dg=17, run=true},
  {t="N", seg=13, arg="Hand in any Zul'Kunda quests you picked up and take any new quests offered in Booty Bay if they fit your level and log; the logger records them"},
  {t="H", seg=13, arg="Grom'gol Base Camp"},
  {t="N", seg=13, arg="Optional Riverglades detour (Rog'mar) fits here", text="Main line does not need it. You arrive with only 6 quests in the log (1183, 1116, 1106, 1261, 598, 584). Bind at Rog'mar, use Teleport: Orgrimmar/Undercity for training and turn-ins, and the Brill trip for your mount at 40. Stay while its quests are no more than 2-3 levels above you and leave at about 41-43. If Rog'mar is on Kalimdor, Teleport: Thunder Bluff from here and walk in, then come back with Teleport: Undercity to start the next segment; if it is near Hillsbrad or Arathi, enter it from Tarren Mill or Hammerfall at the start of the next segment instead. Coming back at 41+? The first step of the next segment says how to handle its lower quests."},
  {t="L", seg=13, lvl=37, text="If you skipped the detour and are not 37 yet: grind the Bloodscalp trolls around Zul'Kunda (TUGs' troll area, level 34-37), or the Lashtail Raptors and Mosh'Ogg ogres just east of Grom'gol. Pull two or three and Blizzard them."},
  {t="N", seg=14, arg="Coming back from the Riverglades detour at 41 or higher?", text="Do this segment anyway. Most of its quests are level 38-40 and give full XP until you are 5 levels above them; only the level 35-37 ones (663, 701/847, 710, 1389, 1418) start to lose some at 41-43. The next segments also need the Kargath flight path and quests 669, 712 and 1137 from here, and 710 is what unlocks 711/712."},
  {t="N", seg=14, arg="Teleport to Undercity (or take the zeppelin from Grom'gol if you don't have it)", text="Start saving gold now: riding and a horse at 40 cost roughly 90-100g."},
  {t="A", seg=14, q={1953}, names={"Return to the Marsh"}, text="Anastasia Hartwell, a mage trainer in the Magic Quarter. It is handed in to Tabetha in Dustwallow Marsh later (segment 16).", zone="Undercity", map=1458, x=85.1, y=10.0},
  {t="TRAIN", seg=14, text="Undercity Magic Quarter: learn your level 36 ranks (Blizzard, Fireball, Mana Shield) if you did not get them in Orgrimmar, and buy Runes of Teleportation."},
  {t="FLY", seg=14, arg="Hammerfall", text="Bat handler Michael Garrett. (Melor's Frostmaw, 1136, is not part of this route.)", zone="Undercity", map=1458, x=63.2, y=48.6},
  {t="T", seg=14, q={96988}, names={"Source of Power"}, zone="Undercity", map=1458, x=46.6, y=74.4, dg=7},
  {t="A", seg=14, q={1113}, names={"Hearts of Zeal"}, text="Master Apothecary Faranell. 20 Hearts of Zeal from any Scarlet enemies in the monastery.", zone="Undercity", map=1458, x=48.8, y=69.3, dg=10, req=1109},
  {t="A", seg=14, q={1048}, names={"Into The Scarlet Monastery"}, text="Varimathras in the Royal Quarter. Kill Houndmaster Loksey (Library), Herod (Armory), and Mograine and Whitemane (Cathedral). Needs level 33.", zone="Undercity", map=1458, x=56.2, y=92.2, dg=10},
  {t="N", seg=14, arg="Optional dungeon: Scarlet Monastery, levels 30-46", text="The monastery is in the north-east corner of Tirisfal Glades; from Undercity ride east past Brill and north at the Bulwark road. It has four wings, each its own run: Graveyard (30-38), Library (33-41), Armory (36-44) and Cathedral (38-46). Inside the Graveyard wing, Vorrel Sengutz gives Vorrel's Revenge (the ring drops in the Graveyard wing; hand in to Monika Sengutz in Tarren Mill). Quests you picked up for it: Hearts of Zeal, Into The Scarlet Monastery.", zone="Tirisfal Glades", map=1420, x=82.6, y=33.8, dg=10, run=true},
  {t="T", seg=14, q={1048}, names={"Into The Scarlet Monastery"}, zone="Undercity", map=1458, x=56.2, y=92.2, dg=10},
  {t="T", seg=14, q={1113}, names={"Hearts of Zeal"}, zone="Undercity", map=1458, x=48.8, y=69.3, dg=10},
  {t="A", seg=14, q={2342}, names={"Reclaimed Treasures"}, text="Patrick Garrett in the Trade Quarter. His family chest is in the South Common Hall, before the dungeon portal.", zone="Undercity", map=1458, x=62.3, y=48.6, dg=12},
  {t="A", seg=14, q={701}, names={"Guile of the Raptor"}, text="Tor'gan. He offered it after Raising Spirits in segment 11.", zone="Arathi Highlands", map=1417, x=74.7, y=36.3},
  {t="A", seg=14, q={678}, names={"Call to Arms"}, text="Drum Fel. The second Call to Arms, left with him in segment 11.", zone="Arathi Highlands", map=1417, x=74.2, y=33.9},
  {t="C", seg=14, q={701,678}, names={"Guile of the Raptor","Call to Arms"}, text="Boulderfist Hall, south-west of Hammerfall. Highland Fleshstalker raptors roam the hills around it (hearts drop about one time in three); the Brutes and Magi are in and around the ogre cave.", zone="Arathi Highlands", map=1417, x=52.0, y=75.0, path={{73.4,30.7},{70.8,31.9},{70.6,35.8},{68.8,38.5},{68.8,45.4},{66.0,51.0},{60.0,51.0},{58.0,53.1},{57.8,57.3},{54.0,63.0},{53.9,76.8}}, cave=true},
  {t="T", seg=14, q={701}, names={"Guile of the Raptor"}, text="Tor'gan", zone="Arathi Highlands", map=1417, x=74.7, y=36.3, path={{54.6,61.5},{57.8,56.7},{58.0,53.1},{59.4,51.0},{66.0,51.0},{68.8,46.9},{68.8,41.2},{70.4,38.5},{71.6,30.7},{76.7,32.8},{76.7,35.8}}},
  {t="A", seg=14, q={702}, names={"Guile of the Raptor"}, text="Tor'gan", zone="Arathi Highlands", map=1417, x=74.7, y=36.3},
  {t="T", seg=14, q={702}, names={"Guile of the Raptor"}, text="Gor'mul", zone="Arathi Highlands", map=1417, x=72.6, y=33.9},
  {t="A", seg=14, q={847}, names={"Guile of the Raptor"}, text="Gor'mul", zone="Arathi Highlands", map=1417, x=72.6, y=33.9},
  {t="T", seg=14, q={847}, names={"Guile of the Raptor"}, text="Back to Tor'gan", zone="Arathi Highlands", map=1417, x=74.7, y=36.3},
  {t="T", seg=14, q={678}, names={"Call to Arms"}, text="Drum Fel. Skip the follow-ups 679 and 680: both are elite.", zone="Arathi Highlands", map=1417, x=74.2, y=33.9},
  {t="A", seg=14, q={663}, names={"Land Ho!"}, text="Lolo the Lookout at Faldir's Cove. These quests are level 40: Frost Nova and Polymorph help a lot against the naga.", zone="Arathi Highlands", map=1417, x=31.8, y=82.7},
  {t="T", seg=14, q={663}, names={"Land Ho!"}, text="Shakes O'Breen", zone="Arathi Highlands", map=1417, x=32.3, y=81.4},
  {t="A", seg=14, q={662,664,665}, names={"Deep Sea Salvage","Drowned Sorrows","Sunken Treasure"}, text="First Mate Nilzlix, Captain Steelgut and Professor Phizzlethorpe, all in the camp", zone="Arathi Highlands", map=1417, x=32.8, y=81.5},
  {t="C", seg=14, q={665}, names={"Sunken Treasure"}, text="Escort the professor to the nearby sea cave and back. Expect attacks on the way: stay close and keep him alive.", zone="Arathi Highlands", map=1417, x=33.9, y=80.5},
  {t="T", seg=14, q={665}, names={"Sunken Treasure"}, text="Doctor Draxlegauge", zone="Arathi Highlands", map=1417, x=33.9, y=80.4},
  {t="A", seg=14, q={666}, names={"Sunken Treasure"}, text="Doctor Draxlegauge. Equip the Goggles of Gem Hunting to see the calcified gems on the sea floor.", zone="Arathi Highlands", map=1417, x=33.9, y=80.5},
  {t="C", seg=14, q={662,664,666}, names={"Deep Sea Salvage","Drowned Sorrows","Sunken Treasure"}, text="West of the cove. The charts and logs are inside the two wrecks (Maiden's Folly and Spirit of Silverpine), the gems lie on the sea floor around them, the Daggerspine Raiders and Sorceresses are on the reef and shore. Undead breathe far longer underwater, so no potion is needed. Pull the naga one at a time.", zone="Arathi Highlands", map=1417, x=21.5, y=86.0},
  {t="T", seg=14, q={662}, names={"Deep Sea Salvage"}, text="Nilzlix", zone="Arathi Highlands", map=1417, x=32.8, y=81.5},
  {t="T", seg=14, q={664}, names={"Drowned Sorrows"}, text="Steelgut", zone="Arathi Highlands", map=1417, x=34.0, y=80.8},
  {t="T", seg=14, q={666}, names={"Sunken Treasure"}, text="Draxlegauge, return the goggles", zone="Arathi Highlands", map=1417, x=33.9, y=80.5},
  {t="A", seg=14, q={668}, names={"Sunken Treasure"}, text="Draxlegauge", zone="Arathi Highlands", map=1417, x=33.9, y=80.4},
  {t="T", seg=14, q={668}, names={"Sunken Treasure"}, text="Shakes O'Breen", zone="Arathi Highlands", map=1417, x=32.3, y=81.4},
  {t="A", seg=14, q={669}, names={"Sunken Treasure"}, text="Shakes O'Breen. Keep the gem for Fleet Master Seahorn in Booty Bay (segment 15).", zone="Arathi Highlands", map=1417, x=32.3, y=81.4},
  {t="G", seg=14, text="Head east to Thandol Span, the great bridge at the south edge of Arathi. Dark Iron dwarves stand on it.", zone="Arathi Highlands", map=1417, x=48.5, y=87.5},
  {t="G", seg=14, text="Cross the bridge into the Wetlands, keep clear of Dun Modr and follow the road south to the Dun Algaz pass.", zone="Wetlands", map=1437, x=54.2, y=70.3},
  {t="G", seg=14, text="Go through Dun Algaz into Loch Modan. The Alliance mountaineers at the gates are level 30. Head south down the west side of the zone, keeping Thelsamar well to your left (east), to the pass into the Badlands. Mountaineer Pebblebitty (44) stands at the pass: run past him.", zone="Loch Modan", map=1432, x=18.5, y=85.0},
  {t="T", seg=14, q={1106}, names={"Martek the Exiled"}, text="Martek the Exiled, south along the road from the pass. Shadowforge dwarves dig near the pass: don't stray.", zone="Badlands", map=1418, x=42.2, y=52.7},
  {t="A", seg=14, q={1108}, names={"Indurium"}, text="Martek", zone="Badlands", map=1418, x=42.2, y=52.7},
  {t="A", seg=14, q={703}, names={"Barbecued Buzzard Wings"}, text="Rigglefuzz, next to Martek. Skip Pearl Diving (705, elite-flagged).", zone="Badlands", map=1418, x=42.4, y=52.9},
  {t="A", seg=14, q={710}, names={"Study of the Elements: Rock"}, text="Lotwil Veriatus, west along the road", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="F", seg=14, arg="Kargath", text="Gorrik, at the west edge of the Badlands", zone="Badlands", map=1418, x=4.0, y=44.8, path={{25.6,47.8},{24.5,49.6},{16.1,49.3},{14.3,46.6},{14.5,43.3},{12.1,41.8},{3.9,41.2},{3.3,43.6}}},
  {t="A", seg=14, q={2258,1419}, names={"Badlands Reagent Run","Coyote Thieves"}, text="Jarkal Mossmeld and Neeka Bloodscar. Gorn's Broken Alliances (782) needs level 40: leave it.", zone="Badlands", map=1418, x=2.4, y=46.1},
  {t="C", seg=14, q={710,2258}, obj={0,3}, names={"Study of the Elements: Rock","Badlands Reagent Run"}, text="Lesser rock elementals between Kargath and Lotwil's camp. Rock elemental shards drop from them too.", zone="Badlands", map=1418, x=18.8, y=43.0},
  {t="T", seg=14, q={710}, names={"Study of the Elements: Rock"}, text="Lotwil", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="A", seg=14, q={711}, names={"Study of the Elements: Rock"}, text="Lotwil", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="C", seg=14, q={1419,2258,703}, names={"Coyote Thieves","Badlands Reagent Run","Barbecued Buzzard Wings"}, text="South of Lotwil's camp: Elder Crag Coyotes for the jawbones and fangs, Giant Buzzards for the gizzards and wings.", zone="Badlands", map=1418, x=26.0, y=62.0},
  {t="C", seg=14, q={711}, names={"Study of the Elements: Rock"}, text="Rock Elementals (39-40) in the rocky hills just south-west of the Stonevault trogg camp. You need 3 slabs and nearly every kill drops one. They hit hard but have no ranged attack: Frostbolt, Frost Nova, step back.", zone="Badlands", map=1418, x=41.0, y=79.0},
  {t="C", seg=14, q={1108}, names={"Indurium"}, text="Stonevault trogg camp. Only the Stonevault Bonesnappers and Shamans here drop the indurium flakes (about 60%). Still short of jawbones, fangs, gizzards or wings? The Feral Crag Coyotes and Buzzards around this camp drop those.", zone="Badlands", map=1418, x=50.5, y=68.0},
  {t="A", seg=14, q={709}, names={"Solution to Doom"}, text="Theldurin the Lost. The Tablet of Ryun'eh is in the tunnels before the dungeon portal.", zone="Badlands", map=1418, x=51.4, y=76.9, dg=12},
  {t="T", seg=14, q={1108}, names={"Indurium"}, text="Martek", zone="Badlands", map=1418, x=42.2, y=52.7},
  {t="A", seg=14, q={1137}, names={"News for Fizzle"}, text="Martek. This goes to Fizzle on the Shimmering Flats (segment 16).", zone="Badlands", map=1418, x=42.2, y=52.7},
  {t="T", seg=14, q={703}, names={"Barbecued Buzzard Wings"}, text="Rigglefuzz", zone="Badlands", map=1418, x=42.4, y=52.9},
  {t="A", seg=14, q={2418}, names={"Power Stones"}, text="Rigglefuzz. Power Stones drop from the Shadowforge dwarves in and around Uldaman.", zone="Badlands", map=1418, x=42.4, y=52.9, dg=12},
  {t="T", seg=14, q={711}, names={"Study of the Elements: Rock"}, text="Lotwil", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="A", seg=14, q={712}, names={"Study of the Elements: Rock"}, text="Lotwil. Greater rock elementals (42-44, far south-west) drop the bracers: kill them only if you are comfortable, segment 15 finishes this.", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="T", seg=14, q={2258}, names={"Badlands Reagent Run"}, text="Jarkal. Do not take Uldaman Reagent Run (2202): it is a dungeon quest.", zone="Badlands", map=1418, x=2.4, y=46.1, path={{25.6,47.8},{24.5,49.6},{21.1,49.9},{16.9,56.1},{12.9,59.4},{8.5,59.1},{6.7,56.1},{5.9,51.0}}},
  {t="T", seg=14, q={1419}, names={"Coyote Thieves"}, text="Neeka Bloodscar", zone="Badlands", map=1418, x=6.5, y=47.2},
  {t="L", seg=14, lvl=39, text="Quest XP runs out here. Grind the lesser rock elementals between Kargath and Lotwil's camp, or the Rock Elementals (39-40) on the hill north-east of Kargath at 14,34 (TUGs' elemental grind). The Stonevault troggs drop coins and cloth if you would rather save for the mount.", zone="Badlands", map=1418, x=18.0, y=44.0},
  {t="N", seg=14, arg="Teleport to Undercity", text="No rune or no Teleport yet? Hearth to Grom'gol now, skip the training and train at 40 in the next segment."},
  {t="TRAIN", seg=14, text="Undercity Magic Quarter: learn your level 38 spells and restock Runes of Teleportation."},
  {t="H", seg=14, arg="Grom'gol Base Camp", text="Your hearthstone is still set to Grom'gol. If you bound at Rog'mar on the Riverglades detour, take the zeppelin to Grom'gol from the tower outside Undercity instead."},
  {t="N", seg=14, arg="Run from Grom'gol to the Swamp of Sorrows", text="North out of Grom'gol into Duskwood, then east along the road. Go round Darkshire (Alliance guards), take the road east through Deadwind Pass and follow it into the swamp."},
  {t="C", seg=14, q={1116}, names={"Dream Dust in the Swamp"}, text="Dreaming and adolescent whelps in the misty valley at the west end of the swamp, by the road. If the dust drops slowly, segment 15 can finish it on the dragonkin east of Stonard.", zone="Swamp of Sorrows", map=1435, x=14.0, y=61.0},
  {t="F", seg=14, arg="Stonard", text="Breyk", zone="Swamp of Sorrows", map=1435, x=46.1, y=54.8},
  {t="A", seg=14, q={1418}, names={"Neeka Bloodscar"}, text="Helgrum the Swift, next to the flight master. Keep it: you fly to Kargath at the start of the next segment, where Neeka takes it.", zone="Swamp of Sorrows", map=1435, x=47.7, y=55.2},
  {t="S", seg=14, arg="Stonard", text="Innkeeper Karakul", zone="Swamp of Sorrows", map=1435, x=45.2, y=56.7},
  {t="A", seg=14, q={698}, names={"Lack of Surplus"}, text="Dar", zone="Swamp of Sorrows", map=1435, x=44.7, y=57.2},
  {t="A", seg=14, q={93663}, names={"Lost in Transit"}, text="Dar: Lost in Transit (new in Forever, needs level 30). Her courier never reached the Harborage", zone="Swamp of Sorrows", map=1435, x=44.7, y=57.2},
  {t="C", seg=14, q={93663}, names={"Lost in Transit"}, text="Find the Courier's Shipment. The quest only says \"check near the waters along the road\": follow the road from Stonard north-west toward the Harborage and look at every pool and stream bank beside it (the arrow is a guess at the middle of that road). Crocolisks may guard it", zone="Swamp of Sorrows", map=1435, x=36.0, y=44.0},
  {t="N", seg=14, arg="Take any other new quests offered in Stonard; the logger records them"},
  {t="A", seg=14, q={1389}, names={"Draenethyst Crystals"}, text="Magtoor at the Harborage, the draenei village in the north-west", zone="Swamp of Sorrows", map=1435, x=26.0, y=31.4},
  {t="T", seg=14, q={93663}, names={"Lost in Transit"}, text="Magtoor: Dar's shipment. Not found on the way? Press Skip and look again on your way back to Stonard", zone="Swamp of Sorrows", map=1435, x=26.0, y=31.4},
  {t="N", seg=14, arg="Take any new quests offered at the Harborage; the logger records them", text="Several new Forever quests here are done at Fallow Sanctuary with the crystals (killing Lost Ones, a stolen lure on the banks east of here). Hand them in when you come back. Skip The Visiting Mage (93464): it sends you to a mage in Desolace, which this route does not revisit.", zone="Swamp of Sorrows", map=1435, x=26.0, y=31.4},
  {t="C", seg=14, q={1389}, names={"Draenethyst Crystals"}, text="Fallow Sanctuary, east of the Harborage: the crystals sit among the Lost Ones' huts and campfires. Kill sawtooth crocolisks for 698 on the way.", zone="Swamp of Sorrows", map=1435, x=62.4, y=22.7},
  {t="A", seg=14, q={1393}, names={"Galen's Escape"}, text="Galen Goodward, just north-east of the crystals. Accepting starts the escort.", zone="Swamp of Sorrows", map=1435, x=65.5, y=18.2},
  {t="C", seg=14, q={1393}, names={"Galen's Escape"}, text="Keep Galen alive until he says he is safe.", zone="Swamp of Sorrows", map=1435, x=65.5, y=18.2},
  {t="T", seg=14, q={1393}, names={"Galen's Escape"}, text="Galen's strongbox at his camp, north of Stonard", zone="Swamp of Sorrows", map=1435, x=47.8, y=39.8},
  {t="A", seg=14, q={1392}, names={"Noboru the Cudgel"}, text="Kill Noboru the Cudgel (39). He wanders the area roughly between here and 42,36. His cudgel starts the quest.", zone="Swamp of Sorrows", map=1435, x=55.7, y=34.4},
  {t="C", seg=14, q={698}, names={"Lack of Surplus"}, text="Finish the sawtooth flanks from the crocolisks along the water. Keep them: Tok'Kar on the south-east coast takes them in the next segment, when you ride that coast at 40.", zone="Swamp of Sorrows", map=1435, x=56.0, y=40.0},
  {t="T", seg=14, q={1389,1392}, names={"Draenethyst Crystals","Noboru the Cudgel"}, text="Magtoor. Hand in any new Harborage quests too.", zone="Swamp of Sorrows", map=1435, x=26.0, y=31.4},
  {t="G", seg=14, text="Back to Stonard, where segment 15 starts.", zone="Swamp of Sorrows", map=1435, x=46.0, y=54.6},
  {t="FLY", seg=15, arg="Kargath", text="Breyk, Stonard's wind rider master. Leave the Stonard coast quests for now: their mobs are level 41-45 and you come back at 40 with a mount. Your hearthstone stays set to Stonard"},
  {t="T", seg=15, q={1418}, names={"Neeka Bloodscar"}, text="Neeka Bloodscar in Kargath", zone="Badlands", map=1418, x=6.5, y=47.2},
  {t="A", seg=15, q={1420}, names={"Report to Helgrum"}, text="Neeka. Keep her report until you hearth back to Stonard", zone="Badlands", map=1418, x=6.5, y=47.2},
  {t="L", seg=15, lvl=40, text="Rock Elementals (39-40) on the slopes north-east of Kargath, then the Lesser Rock Elementals (37-39) along the way east toward Lotwil's camp. They hit hard but have no ranged attacks: Frostbolt, Frost Nova, step back. If they are thin or taken, TUGs' bigger Rock Elemental spot is in the south around 41,79: ride back to Kargath once you are 40", zone="Badlands", map=1418, x=14.5, y=35.0},
  {t="A", seg=15, q={782}, names={"Broken Alliances"}, text="Gorn in Kargath, now that you are 40", zone="Badlands", map=1418, x=2.9, y=45.6},
  {t="C", seg=15, q={712}, names={"Study of the Elements: Rock"}, text="Greater Rock Elementals (42-44) in the far south-west corner of the Badlands drop Bracers of Rock Binding on most kills. Pull one at a time and kite it. The Dustbelcher ogre camp (Camp Boff) sits right between this group and a second one to the south-east, so pull from the edges and do not drift into the ogres. Kill Boss Tho'grun (next step) if he walks past", zone="Badlands", map=1418, x=4.1, y=79.6, path={{0.1,45.7},{0.1,79.5},{0.9,80.7}}},
  {t="C", seg=15, q={782}, names={"Broken Alliances"}, text="Boss Tho'grun (41-42, not elite) starts at Camp Boff and walks a long loop east along the southern road and back. Catch him on the road, away from the Maulers and Shamans (41-43) in the camp, and loot the Sign of the Earth", zone="Badlands", map=1418, x=12.6, y=75.5},
  {t="T", seg=15, q={712}, names={"Study of the Elements: Rock"}, text="Lotwil Veriatus at his camp in western Badlands", zone="Badlands", map=1418, x=25.9, y=44.9},
  {t="N", seg=15, arg="Optional, Auction House only: with Frost Oil and a Gyrochronatom, Lotwil gives 713 and 714, and only after 714 does 734 -> 777 -> 778 (Fam'retor Guardian) open. Lucien Tosselwrench beside him gives 715 (a Healing Potion and a Lesser Invisibility Potion) and 716 (Patterned Bronze Bracers). Without those items, skip all of them"},
  {t="T", seg=15, q={782}, names={"Broken Alliances"}, text="Gorn, back in Kargath. Skip the next part (793, elite)", zone="Badlands", map=1418, x=2.9, y=45.6, path={{25.6,47.8},{24.5,49.6},{21.1,49.9},{16.9,56.1},{13.1,59.1},{8.5,59.1},{6.7,56.1},{5.9,51.0},{2.9,47.5}}},
  {t="A", seg=15, q={2202}, names={"Uldaman Reagent Run"}, text="Jarkal Mossmeld in Kargath, after his Badlands Reagent Run. Magenta Fungus Caps grow inside.", zone="Badlands", map=1418, x=2.4, y=46.1, dg=12},
  {t="N", seg=15, arg="Optional dungeon: Uldaman, levels 41-51", text="The main entrance is the dig site in the north of the Badlands; a back entrance is further east (Badlands 65.2, 43.5). Inside: the Necklace Recovery chain continues (a paladin's remains, then gems from three bosses, with trips back to Jarkal in Kargath), and the Discs of Norgannon after the last boss give The Platinum Discs. Quests you picked up for it: Necklace Recovery, Reclaimed Treasures, Power Stones, Solution to Doom, Uldaman Reagent Run. The route does not come back to these hand-ins, go when it suits you: Power Stones (Badlands); Solution to Doom (Badlands).", zone="Badlands", map=1418, x=44.6, y=12.1, dg=12, run=true},
  {t="T", seg=15, q={2202}, names={"Uldaman Reagent Run"}, zone="Badlands", map=1418, x=2.4, y=46.1, dg=12},
  {t="N", seg=15, arg="Optional dungeon: Krol'dok Stronghold, levels 40-45", text="New Forever dungeon, not checked in game yet. It is in the Riverglades, the new zone east of the Badlands: a fortress on a hill at about 48.6, 26.3 on the Riverglades map. Horde players fly to Rog'mar. No Horde quest givers are published yet: take any dungeon quests you are offered in Rog'mar and the addon logs them so these steps can be filled in.", dg=18, run=true},
  {t="N", seg=15, arg="Teleport: Undercity", text="No Teleport yet? Fly from Kargath to Undercity instead (your hearthstone is set to Stonard)"},
  {t="TRAIN", seg=15, text="Undercity Magic Quarter: learn your level 40 spells"},
  {t="G", seg=15, text="Leave Undercity and walk north up the road to Brill. Velma Warnam (riding) and Zachariah Post (horses) stand together just west of the inn", zone="Tirisfal Glades", map=1420, x=60.0, y=52.6},
  {t="T", seg=15, q={92422}, names={"The Wrath of Rath'mael"}, zone="Tirisfal Glades", map=1420, x=65.2, y=60.2, dg=2},
  {t="N", seg=15, arg="Learn riding from Velma Warnam and buy a skeletal horse from Zachariah Post (Classic: roughly 90-100g for both). Not enough gold? Skip it, keep going on foot and buy it on a later Undercity visit"},
  {t="FLY", seg=15, arg="Tarren Mill", text="Ride back into Undercity and take a bat from the flight master"},
  {t="A", seg=15, q={566}, names={"WANTED: Baron Vardus"}, text="The WANTED poster in Tarren Mill", zone="Hillsbrad Foothills", map=1424, x=62.6, y=20.8},
  {t="T", seg=15, q={1051}, names={"Vorrel's Revenge"}, text="Vorrel's Revenge: Monika Sengutz in the Tarren Mill inn.", zone="Hillsbrad Foothills", map=1424, x=62.7, y=18.9, dg=10},
  {t="A", seg=15, q={507}, names={"Lord Aliden Perenolde"}, text="Krusk. He only offers it if you freed Gol'dir and handed in Blackmoore's Legacy (506) in segment 11. If he has nothing for you, skip the 507 and 508 steps below", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="C", seg=15, q={566}, names={"WANTED: Baron Vardus"}, text="Ride north from Tarren Mill into Alterac Mountains, up to the Uplands at the north edge of the zone. Baron Vardus (40) stands there with Syndicate guards near him: Polymorph one, kill him and take his head. Keep away from the elite Crushridge ogres in the middle of the zone", zone="Alterac Mountains", map=1416, x=47.8, y=17.1},
  {t="C", seg=15, q={507}, names={"Lord Aliden Perenolde"}, text="Perenolde's manor lies west of the Uplands, by the shore of Lordamere Lake. Lord Aliden Perenolde (41) is inside, with Syndicate Assassins and Enforcers (38-40) around the manor. Clear them one pull at a time, then kill him", zone="Alterac Mountains", map=1416, x=39.3, y=14.6, path={{47.6,18.4},{43.6,18.1}}},
  {t="T", seg=15, q={507}, names={"Lord Aliden Perenolde"}, text="Talk to Elysa, who stands right next to him", zone="Alterac Mountains", map=1416, x=39.3, y=14.3},
  {t="A", seg=15, q={508}, names={"Taretha's Gift"}, text="Elysa gives you Taretha's pendant", zone="Alterac Mountains", map=1416, x=39.3, y=14.3},
  {t="T", seg=15, q={508}, names={"Taretha's Gift"}, text="Back in Tarren Mill: Krusk", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="T", seg=15, q={566}, names={"WANTED: Baron Vardus"}, text="High Executor Darthalia, beside the poster", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.5},
  {t="H", seg=15, arg="Stonard", text="Hearth back to Stonard (still bound there). Hearthstone on cooldown? Fly Tarren Mill to Stonard"},
  {t="T", seg=15, q={1420}, names={"Report to Helgrum"}, text="Helgrum the Swift, next to the wind rider master", zone="Swamp of Sorrows", map=1435, x=47.7, y=55.2},
  {t="A", seg=15, q={1430}, names={"Fresh Meat"}, text="Dar in Stonard", zone="Swamp of Sorrows", map=1435, x=44.7, y=57.2},
  {t="N", seg=15, arg="Take any new quests offered in Stonard: Forever added several Swamp quests that have no giver data yet. The logger records them"},
  {t="C", seg=15, q={1116}, names={"Dream Dust in the Swamp"}, text="Specks of Dream Dust drop from about 1 in 5 of the green dragonkin east of Stonard: Green Scalebanes and Scalebane Captains here, more of them further east toward the coast. Avoid the Elder Dragonkin (45)", zone="Swamp of Sorrows", map=1435, x=62.5, y=41.0},
  {t="T", seg=15, q={698}, names={"Lack of Surplus"}, text="Ride east to the coast, then south along the beach to Tok'Kar at Misty Reed Post. Kill every Monstrous Crawler (43-44) you pass: their legs for Fresh Meat (1430) drop only rarely", zone="Swamp of Sorrows", map=1435, x=81.3, y=81.0},
  {t="A", seg=15, q={699}, names={"Lack of Surplus"}, text="Tok'Kar", zone="Swamp of Sorrows", map=1435, x=81.3, y=81.0},
  {t="C", seg=15, q={699}, names={"Lack of Surplus"}, text="Sawtooth Snappers in the shallows along the south coast, south of the camp: claws drop on most kills. Two more crawlers walk this shore. Short of snappers? More of them live along the east coast", zone="Swamp of Sorrows", map=1435, x=78.0, y=97.5},
  {t="T", seg=15, q={699}, names={"Lack of Surplus"}, text="Tok'Kar", zone="Swamp of Sorrows", map=1435, x=81.3, y=81.0},
  {t="A", seg=15, q={1422}, names={"Threat From the Sea"}, zone="Swamp of Sorrows", map=1435, x=81.3, y=81.0},
  {t="T", seg=15, q={1422}, names={"Threat From the Sea"}, text="Katar, a few steps away", zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="A", seg=15, q={1426}, names={"Threat From the Sea"}, text="Katar", zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="C", seg=15, q={1426}, names={"Threat From the Sea"}, text="The few Marsh Murlocs are on the beach just south of the camp, and Inkspewers line the whole south and east coast. Most Flesheaters are on the beach west of the camp around 63,86, the same beach you use for Continued Threat: finish 1426 there and wait for respawns if needed. Pull them away from the groups; Frost Nova and Cone of Cold", zone="Swamp of Sorrows", map=1435, x=84.4, y=88.6},
  {t="T", seg=15, q={1426}, names={"Threat From the Sea"}, text="Katar", zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="A", seg=15, q={1427}, names={"Threat From the Sea"}, zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="T", seg=15, q={1427}, names={"Threat From the Sea"}, text="Tok'Kar", zone="Swamp of Sorrows", map=1435, x=81.3, y=81.0},
  {t="A", seg=15, q={1428}, names={"Continued Threat"}, text="Katar", zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="C", seg=15, q={1428}, names={"Continued Threat"}, text="Inkspewers, Flesheaters and Oracles further west along the southern beach. Kill Oracles first: they heal", zone="Swamp of Sorrows", map=1435, x=64.4, y=81.1},
  {t="T", seg=15, q={1428}, names={"Continued Threat"}, text="Katar", zone="Swamp of Sorrows", map=1435, x=83.8, y=80.4},
  {t="C", seg=15, q={1430}, names={"Fresh Meat"}, text="Still short of crawler legs? Ride north along the east beach once more: most Monstrous Crawlers walk there, and they have respawned by now. If the legs still will not drop, give up on 1430 rather than camp the beach", zone="Swamp of Sorrows", map=1435, x=93.5, y=45.0},
  {t="T", seg=15, q={1430}, names={"Fresh Meat"}, text="Ride back to Stonard: Dar", zone="Swamp of Sorrows", map=1435, x=44.7, y=57.2},
  {t="FLY", seg=15, arg="Grom'gol", text="Breyk, Stonard's wind rider master"},
  {t="A", seg=15, q={572}, names={"Mok'thardin's Enchantment"}, text="Far Seer Mok'thardin. The Jungle Stalkers for it are in central Stranglethorn, later in this segment", zone="Stranglethorn Vale", map=1434, x=32.1, y=29.2},
  {t="C", seg=15, q={584}, names={"Bloodscalp Clan Heads"}, text="584 is already in your log from your last visit. Ruins of Zul'Kunda in the far north-west: Gan'zulah (41) and Nezzliok the Dire (40) stand inside the ruins among Bloodscalp trolls. Clear around each one first, then kill them for their heads", zone="Stranglethorn Vale", map=1434, x=23.5, y=8.8, path={{34.2,29.2},{35.8,26.5},{35.8,23.8},{32.0,20.8},{32.0,18.7},{28.2,13.6},{27.4,9.1}}},
  {t="A", seg=15, q={196}, names={"Raptor Mastery"}, text="Hemet Nesingwary, a short ride east of Zul'Kunda at the hunters' camp", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="T", seg=15, q={584}, names={"Bloodscalp Clan Heads"}, text="The Bubbling Cauldron in the middle of Grom'gol", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.6},
  {t="A", seg=15, q={585,586}, names={"Speaking with Nezzliok","Speaking with Gan'zulah"}, text="Both come from the cauldron. They are done in central Stranglethorn after Booty Bay", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.6},
  {t="FLY", seg=15, arg="Booty Bay", text="Thysta, Grom'gol's wind rider master"},
  {t="T", seg=15, q={669}, names={"Sunken Treasure"}, text="Fleet Master Seahorn. He then offers 670, which only sends you back to Faldir's Cove in Arathi: skip it (and 667 after it)", zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="T", seg=15, q={1116}, names={"Dream Dust in the Swamp"}, text="Krazek. Leave his next quest (1117) until you come back to Booty Bay at the end of this segment", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2},
  {t="A", seg=15, q={595}, names={"The Bloodsail Buccaneers"}, text="First Mate Crazz", zone="Stranglethorn Vale", map=1434, x=28.1, y=76.2},
  {t="A", seg=15, q={606}, names={"Scaring Shaky"}, text="\"Sea Wolf\" MacKinley", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="A", seg=15, q={617}, names={"Akiris by the Bundle"}, text="Privateer Bloads", zone="Stranglethorn Vale", map=1434, x=26.8, y=76.4},
  {t="A", seg=15, q={600,621}, names={"Venture Company Mining","Zanzil's Secret"}, text="Crank Fizzlebub", zone="Stranglethorn Vale", map=1434, x=27.1, y=77.2},
  {t="A", seg=15, q={209}, names={"Skullsplitter Tusks"}, text="Kebok", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.1},
  {t="A", seg=15, q={348}, names={"Stranglethorn Fever"}, text="Fin Fizracket", zone="Stranglethorn Vale", map=1434, x=27.6, y=76.7},
  {t="S", seg=15, arg="Booty Bay", text="Innkeeper Skindle"},
  {t="N", seg=15, arg="Take any new quests offered in Booty Bay; the logger records them. Leave the half-buried bottles on the beaches alone: Message in a Bottle (594) needs level 45"},
  {t="T", seg=15, q={595}, names={"The Bloodsail Buccaneers"}, text="Take the road north out of Booty Bay to the pirate cove. The Bloodsail Correspondence lies in the camp, guarded by Bloodsail Raiders and Mages (39-41)", zone="Stranglethorn Vale", map=1434, x=27.3, y=69.5},
  {t="A", seg=15, q={597}, names={"The Bloodsail Buccaneers"}, text="From the same papers", zone="Stranglethorn Vale", map=1434, x=27.3, y=69.5},
  {t="C", seg=15, q={617}, names={"Akiris by the Bundle"}, text="Naga Explorers (43-44) walk the beach north of the cove; about 1 in 3 drops Akiris Reed", zone="Stranglethorn Vale", map=1434, x=26.2, y=62.0},
  {t="A", seg=15, q={349}, names={"Stranglethorn Fever"}, text="Witch Doctor Unbagwa, inland to the east among the gorillas of Mistvale Valley", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="C", seg=15, q={606,349}, names={"Scaring Shaky","Stranglethorn Fever"}, text="Elder Mistvale Gorillas around Unbagwa: Mistvale Giblets drop from about 1 in 3, Gorilla Fangs from about half", zone="Stranglethorn Vale", map=1434, x=32.9, y=64.6},
  {t="T", seg=15, q={349}, names={"Stranglethorn Fever"}, text="Hand Unbagwa the fangs. He calls waves of gorillas and then Mokk the Savage (44): stay next to him and kill each wave. Frost Nova and Cone of Cold keep them off you", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="C", seg=15, q={348}, names={"Stranglethorn Fever"}, text="Loot the Heart of Mokk", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="T", seg=15, q={606}, names={"Scaring Shaky"}, text="Back to Booty Bay: \"Shaky\" Phillipe on the dock", zone="Stranglethorn Vale", map=1434, x=26.9, y=73.6},
  {t="A", seg=15, q={607}, names={"Return to MacKinley"}, zone="Stranglethorn Vale", map=1434, x=26.9, y=73.6},
  {t="T", seg=15, q={597}, names={"The Bloodsail Buccaneers"}, text="First Mate Crazz", zone="Stranglethorn Vale", map=1434, x=28.1, y=76.2},
  {t="A", seg=15, q={599}, names={"The Bloodsail Buccaneers"}, zone="Stranglethorn Vale", map=1434, x=28.1, y=76.2},
  {t="T", seg=15, q={599}, names={"The Bloodsail Buccaneers"}, text="Fleet Master Seahorn", zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="A", seg=15, q={604}, names={"The Bloodsail Buccaneers"}, zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="T", seg=15, q={607}, names={"Return to MacKinley"}, text="\"Sea Wolf\" MacKinley", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="A", seg=15, q={609}, names={"Voodoo Dues"}, text="Keep it for central Stranglethorn", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="T", seg=15, q={617}, names={"Akiris by the Bundle"}, text="Privateer Bloads", zone="Stranglethorn Vale", map=1434, x=26.8, y=76.4},
  {t="T", seg=15, q={348}, names={"Stranglethorn Fever"}, text="Fin Fizracket", zone="Stranglethorn Vale", map=1434, x=27.6, y=76.7},
  {t="A", seg=15, q={587}, names={"Up to Snuff"}, text="Deeg", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.3},
  {t="A", seg=15, q={576}, names={"Keep An Eye Out"}, text="Dizzy One-Eye", zone="Stranglethorn Vale", map=1434, x=28.6, y=75.9},
  {t="C", seg=15, q={604,587}, names={"The Bloodsail Buccaneers","Up to Snuff"}, text="The Bloodsail camp on the shore just south of Booty Bay: kill 10 Swashbucklers and pick up the Bloodsail Charts and Orders lying in the camp. Snuff drops from any Bloodsail pirate. Dizzy's Eye (576) drops only rarely from any Bloodsail, including the ship crews you fight for 608 later, so loot everything. Pull one group at a time, Frost Nova, then Blizzard", zone="Stranglethorn Vale", map=1434, x=29.0, y=82.4},
  {t="T", seg=15, q={604}, names={"The Bloodsail Buccaneers"}, text="Fleet Master Seahorn", zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="A", seg=15, q={608}, names={"The Bloodsail Buccaneers"}, text="Keep it for the end of this segment: the captains are level 45-48", zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="T", seg=15, q={587}, names={"Up to Snuff"}, text="Deeg", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.3},
  {t="C", seg=15, q={621,609}, obj={0,3}, names={"Zanzil's Secret","Voodoo Dues"}, text="Ride north-east from Booty Bay to Zanzil's camp. His trolls, zombies and naga (43-44) drop Zanzil's Mixture on about 1 in 3 kills. Chucky \"Ten Thumbs\" (43) is in the camp: kill him for the ring", zone="Stranglethorn Vale", map=1434, x=39.4, y=57.7},
  {t="C", seg=15, q={609,609}, obj={1,2}, names={"Voodoo Dues","Voodoo Dues"}, text="Maury \"Club Foot\" Wilkins and Jon-Jon the Crow (43-44) stand together at the ruins north-west of Zanzil's camp: kill both", zone="Stranglethorn Vale", map=1434, x=35.1, y=51.6},
  {t="C", seg=15, q={572,196}, names={"Mok'thardin's Enchantment","Raptor Mastery"}, text="Jungle Stalkers (40-41), the raptors in the jungle just west of Maury's ruins toward the coast. Kill 10 for Hemet; about 1 in 4 drops a feather for Mok'thardin, so keep going until you have 10. These kills replace part of the grind to 42", zone="Stranglethorn Vale", map=1434, x=28.5, y=46.0},
  {t="C", seg=15, q={600}, names={"Venture Company Mining"}, text="Venture Co. camp just north of the Crystalvein Mine: the miners, tinkerers and surveyors (40-42) drop Singing Blue Crystals on most kills. Good Blizzard packs", zone="Stranglethorn Vale", map=1434, x=41.7, y=43.7, path={{32.8,39.7},{37.4,38.5}}},
  {t="C", seg=15, q={585}, names={"Speaking with Nezzliok"}, text="Skullsplitter ruins to the north: click the trophy skull piles at Ziata'jai, Balia'mah and Zul'Mamwe (the arrow shows the first two; Zul'Mamwe is the south-east ruin)", zone="Stranglethorn Vale", map=1434, x=44.2, y=34.2},
  {t="C", seg=15, q={586,209,598}, names={"Speaking with Gan'zulah","Skullsplitter Tusks","Split Bone Necklace"}, text="Skullsplitter Hunters, Headhunters and Berserkers stand in the Zul'Mamwe ruins; Ana'thek the Cruel (45) walks there and drops the armour. Tusks and necklaces drop from every Skullsplitter, but slowly", zone="Stranglethorn Vale", map=1434, x=46.4, y=43.2},
  {t="L", seg=15, lvl=42, text="TUGs' troll grind spot: not 42 yet, or still missing tusks or necklaces? Keep killing the Skullsplitter Warriors, Axe Throwers and Mystics (39-40) in these ruins", zone="Stranglethorn Vale", map=1434, x=45.4, y=37.0},
  {t="T", seg=15, q={585,586}, names={"Speaking with Nezzliok","Speaking with Gan'zulah"}, text="Ride west to Grom'gol: the Bubbling Cauldron", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.6},
  {t="A", seg=15, q={588}, names={"The Fate of Yenniku"}, text="The cauldron again", zone="Stranglethorn Vale", map=1434, x=32.2, y=27.6},
  {t="T", seg=15, q={598,588}, names={"Split Bone Necklace","The Fate of Yenniku"}, text="Kin'weelay", zone="Stranglethorn Vale", map=1434, x=32.3, y=27.7},
  {t="A", seg=15, q={589}, names={"The Singing Crystals"}, zone="Stranglethorn Vale", map=1434, x=32.3, y=27.7},
  {t="T", seg=15, q={572}, names={"Mok'thardin's Enchantment"}, text="Far Seer Mok'thardin. Skip his next quest (571): its Aged Gorilla Sinew is a rare drop from the gorillas near Booty Bay", zone="Stranglethorn Vale", map=1434, x=32.1, y=29.2},
  {t="C", seg=15, q={589}, names={"The Singing Crystals"}, text="Ironjaw Basilisks (43-44) in and around the Crystalvein Mine, just south of the Venture Co. camp: the shards drop on most kills", zone="Stranglethorn Vale", map=1434, x=43.1, y=47.8},
  {t="T", seg=15, q={589}, names={"The Singing Crystals"}, text="Back to Grom'gol: Kin'weelay", zone="Stranglethorn Vale", map=1434, x=32.3, y=27.7},
  {t="T", seg=15, q={196}, names={"Raptor Mastery"}, text="Ride north to Hemet Nesingwary. Skip the next part (Tethis, elite)", zone="Stranglethorn Vale", map=1434, x=35.7, y=10.8},
  {t="H", seg=15, arg="Booty Bay", text="Hearth from Nesingwary's camp (you bound at Booty Bay). Hearthstone on cooldown? Ride back to Grom'gol and fly with Thysta"},
  {t="T", seg=15, q={609}, names={"Voodoo Dues"}, text="\"Sea Wolf\" MacKinley. He then offers 613, an elite quest: skip it", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="A", seg=15, q={2872}, names={"Stoley's Debt"}, text="\"Sea Wolf\" MacKinley. Keep it for Stoley in Steamwheedle Port, Tanaris (next segment)", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="T", seg=15, q={600,621}, names={"Venture Company Mining","Zanzil's Secret"}, text="Crank Fizzlebub", zone="Stranglethorn Vale", map=1434, x=27.1, y=77.2},
  {t="A", seg=15, q={1117}, names={"Rumors for Kravel"}, text="Krazek, beside Crank. Keep it for Kravel Koalbeard on the Shimmering Flats (next segment)", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2},
  {t="T", seg=15, q={209}, names={"Skullsplitter Tusks"}, text="Kebok", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.1},
  {t="C", seg=15, q={608,576}, names={"The Bloodsail Buccaneers","Keep An Eye Out"}, text="The three Bloodsail ships are anchored off the coast south of Booty Bay. Swim out, clear the deckhands and sea dogs (43-45) near each captain one at a time, then kill Captain Stillwater (45-46, east ship) and Captain Keelhaul (46-47, west ship). Fleet Master Firallon (48, south ship) is six levels above you: if your spells keep missing, leave him, keep 608 and finish it at the Booty Bay stop of the 45-48 segment (about level 47). Still no Dizzy's Eye? Any of the ship crews can drop it. Polymorph adds and keep Frost Nova ready", zone="Stranglethorn Vale", map=1434, x=30.9, y=89.0},
  {t="N", seg=15, arg="Cortello's Riddle, a scroll lying on the ship decks, starts 624. Its turn-in is under a bridge in western Swamp of Sorrows and the chain goes on to Dustwallow Marsh and the Hinterlands. This route does not carry it: leave it, or take it only if you will hand it in yourself on a later Stonard visit"},
  {t="T", seg=15, q={608}, names={"The Bloodsail Buccaneers"}, text="Fleet Master Seahorn", zone="Stranglethorn Vale", map=1434, x=27.2, y=77.0},
  {t="A", seg=15, q={2864}, names={"Tran'rek"}, text="Krazek in Booty Bay. It sends you to Tran'rek in Gadgetzan.", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2, dg=13},
  {t="T", seg=15, q={576}, names={"Keep An Eye Out"}, text="Dizzy One-Eye, a few steps from Seahorn", zone="Stranglethorn Vale", map=1434, x=28.6, y=75.9},
  {t="N", seg=15, arg="Keep these for later segments: 1117 Rumors for Kravel, 1137 News for Fizzle and 1183 Goblin Sponsorship (Shimmering Flats), 2872 Stoley's Debt (Tanaris), 1953 Return to the Marsh (Tabetha), 1261 Marg Speaks (Brackenwall), plus 608 if you left Firallon for later. The next segment starts here with Teleport: Undercity, where you train 42"},
  {t="N", seg=16, arg="Teleport: Undercity instead of taking the boat (no Teleport yet? Fly to Grom'gol and take the zeppelin to Tirisfal Glades)", text="You start in Booty Bay. This segment uses three Teleports, so carry 4-5 Runes of Teleportation."},
  {t="TRAIN", seg=16, text="Undercity Magic Quarter: learn your level 42 spells if you did not train at the end of the last segment"},
  {t="A", seg=16, q={232}, names={"Errand for Apothecary Zinge"}, text="Apothecary Zinge in the Apothecarium", zone="Undercity", map=1458, x=50.1, y=68.0},
  {t="T", seg=16, q={232}, names={"Errand for Apothecary Zinge"}, text="Alessandro Luca", zone="Undercity", map=1458, x=58.6, y=54.7},
  {t="T", seg=16, q={2342}, names={"Reclaimed Treasures"}, zone="Undercity", map=1458, x=62.3, y=48.6, dg=12},
  {t="A", seg=16, q={238}, names={"Errand for Apothecary Zinge"}, text="Alessandro Luca", zone="Undercity", map=1458, x=58.6, y=54.7},
  {t="A", seg=16, q={3341}, names={"Bring the End"}, text="Andrew Brownell in the Magic Quarter. Kill Amnennar the Coldbringer, the last boss. Needs level 37.", zone="Undercity", map=1458, x=74.0, y=33.3, dg=11},
  {t="T", seg=16, q={238}, names={"Errand for Apothecary Zinge"}, text="Back to Apothecary Zinge", zone="Undercity", map=1458, x=50.1, y=68.0},
  {t="A", seg=16, q={243}, names={"Into the Field"}, text="Apothecary Zinge. You hand this in at Gadgetzan.", zone="Undercity", map=1458, x=50.1, y=68.0},
  {t="N", seg=16, arg="Still no mount?", text="Only if you can afford it now: ride up the road to Brill. Velma Warnam teaches riding and Zachariah Post sells the horses, both just west of the inn. Cast the next Teleport from there. Otherwise skip this step.", zone="Tirisfal Glades", map=1420, x=60.0, y=52.6},
  {t="N", seg=16, arg="Teleport: Thunder Bluff (or take the zeppelin to Orgrimmar and fly to Thunder Bluff if you don't have it)"},
  {t="A", seg=16, q={1205}, names={"Deadmire"}, text="Melor Stonehoof on Hunter's Rise. Deadmire is in Dustwallow Marsh; you bring the tooth back here when you come to train at 44.", zone="Thunder Bluff", map=1456, x=61.5, y=80.9},
  {t="N", seg=16, arg="Optional dungeon: Razorfen Downs, levels 37-46", text="The entrance is at the southern tip of the Barrens, just east of the Great Lift down to Thousand Needles. Fly to Camp Taurajo or Freewind Post and ride. Myriam Moonsinger at the entrance gives A Host of Evil (the enemies it asks for are outside the portal); hand it back to her after the run. Inside: Belnistrasz gives a short quest and then an escort to the idol; Ambassador Malcin (outside the portal) can drop a Small Scroll that starts a quest for Varimathras in Undercity. Quests you picked up for it: Bring the End.", zone="The Barrens", map=1413, x=49.0, y=93.9, dg=11, run=true},
  {t="T", seg=16, q={2280}, names={"The Platinum Discs"}, text="The Platinum Discs: Sage Truthseeker.", zone="Thunder Bluff", map=1456, x=34.4, y=46.9, dg=12},
  {t="FLY", seg=16, arg="Gadgetzan", text="Tal, the wind rider master in Thunder Bluff"},
  {t="S", seg=16, arg="Gadgetzan", text="Innkeeper Fizzgrimble at the inn"},
  {t="T", seg=16, q={243}, names={"Into the Field"}, text="Chief Engineer Bilgewhizzle, in the middle of town", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="A", seg=16, q={379}, names={"Slake That Thirst"}, text="Chief Engineer Bilgewhizzle. Keep it for the Wastewander camps later.", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="T", seg=16, q={1117}, names={"Rumors for Kravel"}, text="Ride north out of Gadgetzan into Thousand Needles and on to the Mirage Raceway. Kravel Koalbeard is on the gnome side of the track. He then offers Back to Booty Bay: skip it.", zone="Thousand Needles", map=1441, x=77.8, y=77.3},
  {t="T", seg=16, q={1137}, names={"News for Fizzle"}, text="Fizzle Brassbolts, also on the gnome side", zone="Thousand Needles", map=1441, x=78.1, y=77.1},
  {t="T", seg=16, q={1183}, names={"Goblin Sponsorship"}, text="Pozzik, on the goblin side of the track", zone="Thousand Needles", map=1441, x=80.2, y=75.9},
  {t="A", seg=16, q={1186}, names={"The Eighteenth Pilot"}, text="Pozzik", zone="Thousand Needles", map=1441, x=80.2, y=75.9},
  {t="T", seg=16, q={1186}, names={"The Eighteenth Pilot"}, text="Razzeric, right next to Pozzik", zone="Thousand Needles", map=1441, x=80.3, y=76.1},
  {t="A", seg=16, q={1187}, names={"Razzeric's Tweaking"}, text="Razzeric. The booster is in a crashed zeppelin in Dustwallow Marsh.", zone="Thousand Needles", map=1441, x=80.3, y=76.1},
  {t="A", seg=16, q={1190}, names={"Keeping Pace"}, text="Pozzik", zone="Thousand Needles", map=1441, x=80.2, y=75.9},
  {t="N", seg=16, arg="Ask Zamek for his distraction", text="Zamek stands on the goblin side. Take Zamek's Distraction from him; while his explosion goes off, run straight to Rizzle's tent on the gnome side.", zone="Thousand Needles", map=1441, x=79.8, y=77.0},
  {t="T", seg=16, q={1190}, names={"Keeping Pace"}, text="Click Rizzle's Unguarded Plans in the tent while Rizzle is away", zone="Thousand Needles", map=1441, x=77.2, y=77.4},
  {t="A", seg=16, q={1194}, names={"Rizzle's Schematics"}, text="From the same plans", zone="Thousand Needles", map=1441, x=77.2, y=77.4},
  {t="T", seg=16, q={1194}, names={"Rizzle's Schematics"}, text="Pozzik", zone="Thousand Needles", map=1441, x=80.2, y=75.9},
  {t="FLY", seg=16, arg="Brackenwall Village", text="Ride back south to Gadgetzan and fly from there"},
  {t="A", seg=16, q={1168}, names={"Army of the Black Dragon"}, text="Tharg", zone="Dustwallow Marsh", map=1445, x=37.4, y=31.4},
  {t="A", seg=16, q={1169}, names={"Identifying the Brood"}, text="Draz'Zilb. Skip Overlord Mok'Morokk's Concern (elite).", zone="Dustwallow Marsh", map=1445, x=37.1, y=33.1},
  {t="T", seg=16, q={1953}, names={"Return to the Marsh"}, text="Ride south down the road to Tabetha's hut. She then offers The Infernal Orb: skip it, the orb drops in Desolace.", zone="Dustwallow Marsh", map=1445, x=46.1, y=57.1},
  {t="A", seg=16, q={2846}, names={"Tiara of the Deep"}, text="Tabetha, in her hut in the marsh. The Tiara of the Deep drops from Hydromancer Velratha.", zone="Dustwallow Marsh", map=1445, x=46.1, y=57.1, dg=13},
  {t="C", seg=16, q={1205}, names={"Deadmire"}, text="Deadmire is a level 45 crocolisk in the water just east of Tabetha's hut. Frost Nova him and kite with Frostbolt.", zone="Dustwallow Marsh", map=1445, x=48.8, y=56.8},
  {t="C", seg=16, q={1187}, names={"Razzeric's Tweaking"}, text="The crashed zeppelin is a short way further east. Loot the Gizmorium Shipping Crate inside the wreck.", zone="Dustwallow Marsh", map=1445, x=54.1, y=56.5},
  {t="C", seg=16, q={1261}, names={"Marg Speaks"}, text="Marg's Jeweled Pendant: ride south-east from the wreck to the shore. Muckshell Clackers, Pincers and Scrabblers (39-43) walk the beach around 54-57, 61-65. Each has about a 5% chance to drop the pendant, so expect roughly 20 kills.", zone="Dustwallow Marsh", map=1445, x=55.8, y=63.0},
  {t="C", seg=16, q={1168,1169}, names={"Army of the Black Dragon","Identifying the Brood"}, text="Ride west along the south of the marsh into the Wyrmbog. Firemane Scouts and Ash Tails are in the north-west part (around 42, 67); Firemane Scalebanes and the Searing Hatchlings and Whelps are further south-east (around 47, 74). The tongues and hearts drop from the hatchlings and whelps. Stay away from the big Onyxia's Lair cave entrance.", zone="Dustwallow Marsh", map=1445, x=41.2, y=66.7, path={{38.2,65.7}}, cave=true},
  {t="T", seg=16, q={1261}, names={"Marg Speaks"}, text="Back in Brackenwall: Nazeer Bloodpike", zone="Dustwallow Marsh", map=1445, x=35.2, y=30.7},
  {t="A", seg=16, q={1262}, names={"Report to Zor"}, text="Nazeer Bloodpike. Keep it for Orgrimmar (next segment).", zone="Dustwallow Marsh", map=1445, x=35.2, y=30.7},
  {t="T", seg=16, q={1168}, names={"Army of the Black Dragon"}, text="Tharg", zone="Dustwallow Marsh", map=1445, x=37.4, y=31.4},
  {t="T", seg=16, q={1169}, names={"Identifying the Brood"}, text="Draz'Zilb", zone="Dustwallow Marsh", map=1445, x=37.1, y=33.1},
  {t="A", seg=16, q={1170}, names={"The Brood of Onyxia"}, text="Draz'Zilb", zone="Dustwallow Marsh", map=1445, x=37.2, y=33.1},
  {t="T", seg=16, q={1170}, names={"The Brood of Onyxia"}, text="Overlord Mok'Morokk", zone="Dustwallow Marsh", map=1445, x=36.3, y=31.4},
  {t="A", seg=16, q={1171}, names={"The Brood of Onyxia"}, text="Overlord Mok'Morokk", zone="Dustwallow Marsh", map=1445, x=36.3, y=31.4},
  {t="T", seg=16, q={1171}, names={"The Brood of Onyxia"}, text="Draz'Zilb. Skip the next part, The Brood of Onyxia (elite).", zone="Dustwallow Marsh", map=1445, x=37.2, y=33.1},
  {t="H", seg=16, arg="Gadgetzan"},
  {t="T", seg=16, q={1187}, names={"Razzeric's Tweaking"}, text="Ride north to the Mirage Raceway: Razzeric", zone="Thousand Needles", map=1441, x=80.3, y=76.1},
  {t="A", seg=16, q={1188}, names={"Safety First"}, text="Razzeric", zone="Thousand Needles", map=1441, x=80.3, y=76.1},
  {t="T", seg=16, q={1188}, names={"Safety First"}, text="Ride back to Gadgetzan: Shreev at the Gizmorium", zone="Tanaris", map=1446, x=51.0, y=27.2},
  {t="A", seg=16, q={1189}, names={"Safety First"}, text="Shreev", zone="Tanaris", map=1446, x=51.0, y=27.2},
  {t="T", seg=16, q={1189}, names={"Safety First"}, text="One more short ride north to Razzeric at the Raceway, then back to Gadgetzan", zone="Thousand Needles", map=1441, x=80.3, y=76.1},
  {t="A", seg=16, q={2770}, names={"Gahz'rilla"}, text="Wizzle Brassbolts at the Mirage Raceway. Gahz'rilla is summoned with the Mallet of Zul'Farrak, which takes its own trip to the Hinterlands; skip this one if your group does not have the mallet.", zone="Thousand Needles", map=1441, x=78.1, y=77.1, dg=13},
  {t="A", seg=16, q={1690}, names={"Wastewander Justice"}, text="Chief Engineer Bilgewhizzle in Gadgetzan", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="A", seg=16, q={1707}, names={"Water Pouch Bounty"}, text="Spigot Operator Luglunket, next to Bilgewhizzle", zone="Tanaris", map=1446, x=52.5, y=28.4},
  {t="A", seg=16, q={2781}, names={"WANTED: Caliph Scorpidsting"}, text="The Wanted poster in Gadgetzan", zone="Tanaris", map=1446, x=51.8, y=27.0},
  {t="C", seg=16, q={1690,1707,379}, names={"Wastewander Justice","Water Pouch Bounty","Slake That Thirst"}, text="The Wastewander Bandits and Thieves camp east of Gadgetzan (around 59-65, 23-33). Any Wastewander can drop a Water Pouch; you need 10 in all (5 for each quest). Pull 2-3 at a time, then Frost Nova and Blizzard.", zone="Tanaris", map=1446, x=62.5, y=29.0},
  {t="L", seg=16, lvl=43, text="Quest XP runs short in this segment. Keep clearing the Wastewander Bandits and Thieves in this camp until level 43. Loot every kill: the OOX-17/TN Distress Beacon (it starts a quest later in this segment) is a rare drop from almost any Tanaris mob.", zone="Tanaris", map=1446, x=62.5, y=29.0},
  {t="T", seg=16, q={1690}, names={"Wastewander Justice"}, text="Chief Engineer Bilgewhizzle", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="A", seg=16, q={1691}, names={"More Wastewander Justice"}, text="Chief Engineer Bilgewhizzle", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="T", seg=16, q={1707}, names={"Water Pouch Bounty"}, text="Spigot Operator Luglunket. Spare pouches can go to him too if he offers the repeatable bounty.", zone="Tanaris", map=1446, x=52.5, y=28.4},
  {t="T", seg=16, q={379}, names={"Slake That Thirst"}, text="Chief Engineer Bilgewhizzle. He gives you the Model 4711-FTZ Power Source. Do NOT right-click it yet: it starts a two-hour timer, so you use it after the level 44 grind.", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="C", seg=16, q={1691,2781}, names={"More Wastewander Justice","WANTED: Caliph Scorpidsting"}, text="The second Wastewander camp is south of the first (around 59-66, 33-41): Shadow Mages, Rogues and Assassins. Caliph Scorpidsting stands in the middle of it at 61.8, 38.2. Clear his guards first, then kill him for his head.", zone="Tanaris", map=1446, x=61.8, y=37.5},
  {t="L", seg=16, lvl=44, text="Keep killing the Shadow Mages, Rogues and Assassins in the south camp until level 44 (you train right after the Gadgetzan hand-ins). The camp respawns quickly, so work in a loop around it.", zone="Tanaris", map=1446, x=61.8, y=37.0},
  {t="A", seg=16, q={654}, names={"Tanaris Field Sampling"}, text="Now right-click the power source at the west edge of the camp. From here you have two hours to collect the samples and hand the kit in, so go straight on.", zone="Tanaris", map=1446, x=58.5, y=35.0},
  {t="C", seg=16, q={654}, names={"Tanaris Field Sampling"}, text="Keep the Field Testing Kit in your bags. On the ride back west to Gadgetzan, kill Glasshide Basilisks, Blisterpaw hyenas and Scorpid Hunters or Tail Lashers; all three roam the flats between the camp and town (about 48-60, 25-40). Loot each one for its sample. Not every sample passes the kit's test, so expect more than 8 kills of each.", zone="Tanaris", map=1446, x=55.0, y=33.0},
  {t="T", seg=16, q={1691,2781}, names={"More Wastewander Justice","WANTED: Caliph Scorpidsting"}, text="Chief Engineer Bilgewhizzle", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="T", seg=16, q={654}, names={"Tanaris Field Sampling"}, text="Chief Engineer Bilgewhizzle", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="A", seg=16, q={864}, names={"Return to Apothecary Zinge"}, text="Chief Engineer Bilgewhizzle. Keep it for the Undercity (later segment).", zone="Tanaris", map=1446, x=52.5, y=28.5},
  {t="N", seg=16, arg="Teleport: Thunder Bluff (or fly there from Gadgetzan if you don't have it)"},
  {t="T", seg=16, q={1205}, names={"Deadmire"}, text="Melor Stonehoof on Hunter's Rise", zone="Thunder Bluff", map=1456, x=61.5, y=80.9},
  {t="TRAIN", seg=16, text="Thunder Bluff, Spirit Rise mage trainers: learn your level 44 spells"},
  {t="H", seg=16, arg="Gadgetzan", text="Faster than the flight back. If the hearthstone is still on cooldown, fly to Gadgetzan instead."},
  {t="A", seg=16, q={992}, names={"Gadgetzan Water Survey"}, text="Senior Surveyor Fizzledowser", zone="Tanaris", map=1446, x=50.2, y=27.5},
  {t="C", seg=16, q={992}, names={"Gadgetzan Water Survey"}, text="Ride west to Sandsorrow Watch. Use the Untapped Dowsing Widget beside the small pool just south of the Sandfury troll huts. The Sandfury trolls are elite (42-44) and stand just east and north-east of the pool, with two rare elites further north. Swing round and come in from the south-west, use the widget at the pool's west edge and leave at once.", zone="Tanaris", map=1446, x=39.0, y=29.3},
  {t="T", seg=16, q={992}, names={"Gadgetzan Water Survey"}, text="Back in Gadgetzan: Senior Surveyor Fizzledowser", zone="Tanaris", map=1446, x=50.2, y=27.5},
  {t="A", seg=16, q={82}, names={"Noxious Lair Investigation"}, text="Senior Surveyor Fizzledowser", zone="Tanaris", map=1446, x=50.2, y=27.5},
  {t="C", seg=16, q={82}, names={"Noxious Lair Investigation"}, text="The Noxious Lair is south-west of Gadgetzan (around 33, 44). The bugs are level 47-50: pull single Tunnelers and Workers from the outer edge (they drop the parts about half the time; Wasps rarely) and do not go deep inside.", zone="Tanaris", map=1446, x=33.5, y=44.5, path={{48.2,25.9},{44.0,29.5},{44.0,35.2},{36.8,48.1},{35.2,47.8}}},
  {t="A", seg=16, q={3161}, names={"Gahz'ridian"}, text="Ride east to Marvon Rivetseeker, who camps by the Broken Pillar in central Tanaris (52.7, 45.9)", zone="Tanaris", map=1446, x=52.7, y=45.9},
  {t="C", seg=16, q={3161}, names={"Gahz'ridian"}, text="Put on the Gahz'ridian Detector (head slot) and ride through the desert south-west of Marvon (around 40-48, 60-72); it shows the buried Gahz'ridian mounds. Click a mound to dig up the ornaments. Swap your own helm back on afterwards.", zone="Tanaris", map=1446, x=45.4, y=68.5, path={{52.8,51.6},{51.6,53.4},{52.2,59.4},{49.2,63.0},{48.8,67.8}}},
  {t="T", seg=16, q={3161}, names={"Gahz'ridian"}, text="Marvon Rivetseeker", zone="Tanaris", map=1446, x=52.7, y=45.9, path={{48.8,67.8},{49.2,63.0},{52.2,59.4},{51.6,53.4},{52.8,51.6}}},
  {t="A", seg=16, q={351}, names={"Find OOX-17/TN!"}, text="Right-click the OOX-17/TN Distress Beacon. It is a rare (about 1%) drop from almost any Tanaris mob: Wastewanders, pirates, beasts and bugs. No beacon yet? Kill Blisterpaw Hyenas, basilisks and scorpids on the ride south-east from Marvon until it drops. If it still has not dropped by the Gaping Chasm, go on without it and do the robot on your next Tanaris visit (next segment).", zone="Tanaris", map=1446, x=60.2, y=64.7},
  {t="T", seg=16, q={351}, names={"Find OOX-17/TN!"}, text="Homing Robot OOX-17/TN, at the edge of the Gaping Chasm (60.2, 64.7)", zone="Tanaris", map=1446, x=60.2, y=64.7},
  {t="A", seg=16, q={648}, names={"Rescue OOX-17/TN!"}, text="Homing Robot OOX-17/TN", zone="Tanaris", map=1446, x=60.2, y=64.7},
  {t="C", seg=16, q={648}, names={"Rescue OOX-17/TN!"}, text="Escort the robot north to Steamwheedle Port. Ambushers come out of the sand: kill them fast or the robot dies. If it fails, go back and talk to the robot again.", zone="Tanaris", map=1446, x=67.0, y=24.0, path={{60.0,59.4},{54.8,51.6},{54.8,45.4},{57.2,41.5},{58.4,41.5},{59.6,37.9},{64.6,31.0},{64.6,26.8}}},
  {t="T", seg=16, q={2872}, names={"Stoley's Debt"}, text="Stoley in Steamwheedle Port", zone="Tanaris", map=1446, x=67.1, y=24.0},
  {t="A", seg=16, q={2873}, names={"Stoley's Shipment"}, text="Stoley", zone="Tanaris", map=1446, x=67.1, y=24.0},
  {t="A", seg=16, q={2875}, names={"WANTED: Andre Firebeard"}, text="The Wanted poster in Steamwheedle Port", zone="Tanaris", map=1446, x=66.8, y=22.3},
  {t="A", seg=16, q={8366}, names={"Southsea Shakedown"}, text="Security Chief Bilgewhizzle", zone="Tanaris", map=1446, x=67.1, y=23.9},
  {t="A", seg=16, q={8365}, names={"Pirate Hats Ahoy!"}, text="Haughty Modiste", zone="Tanaris", map=1446, x=66.6, y=22.3},
  {t="A", seg=16, q={3520}, names={"Screecher Spirits"}, text="Yeh'kinya, beside the Haughty Modiste. Keep it for the next segment: the vale screechers live in Feral Scar Vale in Feralas, and you come back past Yeh'kinya after the Tooga escort.", zone="Tanaris", map=1446, x=67.0, y=22.4},
  {t="C", seg=16, q={2873,2875,8365,8366}, names={"Stoley's Shipment","WANTED: Andre Firebeard","Pirate Hats Ahoy!","Southsea Shakedown"}, text="Lost Rigger Cove, the walled pirate town south down the coast. Stoley's Shipment is the Stolen Cargo near the docks (72.2, 46.8); Andre Firebeard stands at 73.4, 47.1. Every Southsea pirate can drop a hat. Pull small groups out of the walls: Frost Nova, Blizzard, step back. If a Ship Schedule drops, hand it to the Security Chief as well.", zone="Tanaris", map=1446, x=73.5, y=46.5, path={{65.0,22.9},{65.0,39.7},{69.8,47.2}}},
  {t="L", seg=16, lvl=45, text="Stay in Lost Rigger Cove until level 45. The hats are a slow drop, so most of this grind happens on its own, and the pirates come in groups that suit Blizzard.", zone="Tanaris", map=1446, x=73.5, y=46.5},
  {t="T", seg=16, q={2873}, names={"Stoley's Shipment"}, text="Stoley", zone="Tanaris", map=1446, x=67.1, y=24.0, path={{69.8,47.2},{65.0,39.7},{64.6,26.8}}},
  {t="A", seg=16, q={2874}, names={"Deliver to MacKinley"}, text="Stoley. Keep it for Booty Bay (next segment).", zone="Tanaris", map=1446, x=67.1, y=24.0},
  {t="T", seg=16, q={2875,8366}, names={"WANTED: Andre Firebeard","Southsea Shakedown"}, text="Security Chief Bilgewhizzle", zone="Tanaris", map=1446, x=67.1, y=23.9},
  {t="T", seg=16, q={8365}, names={"Pirate Hats Ahoy!"}, text="Haughty Modiste", zone="Tanaris", map=1446, x=66.6, y=22.3},
  {t="T", seg=16, q={82}, names={"Noxious Lair Investigation"}, text="Ride back west along the road to Gadgetzan (or hearth if it is ready): Alchemist Pestlezugg", zone="Tanaris", map=1446, x=50.9, y=27.0, path={{65.0,22.9},{65.0,26.2},{63.8,28.0},{60.0,30.7},{58.8,30.7},{54.4,24.7},{51.2,24.7}}},
  {t="N", seg=16, arg="Keep these for later segments: 2874 Deliver to MacKinley and 648 Rescue OOX-17/TN (Booty Bay), 864 Return to Apothecary Zinge (Undercity), 1262 Report to Zor (Orgrimmar), 3520 Screecher Spirits (Feralas, back to Yeh'kinya). Your hearthstone stays set to Gadgetzan; the next segment starts here with the flight to Freewind Post."},
  {t="N", seg=17, arg="Buy 4-5 Runes of Teleportation before you leave a city", text="This segment uses Teleport: Orgrimmar, Undercity and Thunder Bluff once each. No Teleport spells yet? The fallback travel is given at each step."},
  {t="FLY", seg=17, arg="Freewind Post", text="You start in Gadgetzan. Take the wind rider to Freewind Post in Thousand Needles."},
  {t="N", seg=17, arg="Follow the road west out of Thousand Needles into Feralas; it leads to Camp Mojache", text="About 5 minutes on your mount. The camp sits on the hills in eastern Feralas."},
  {t="F", seg=17, arg="Camp Mojache", text="Shyn, the wind rider master", zone="Feralas", map=1444, x=75.4, y=44.3},
  {t="S", seg=17, arg="Camp Mojache", text="Innkeeper Greul"},
