  {t="A", seg=17, q={3121}, names={"A Strange Request"}, text="Witch Doctor Uzer'i. You hand the shrunken head in at Orgrimmar later in this segment.", zone="Feralas", map=1444, x=74.4, y=43.4},
  {t="N", seg=17, arg="Keep any OOX-22/FE Distress Beacon that drops in Feralas", text="It starts Find OOX-22/FE!, which you do on your second Feralas visit."},
  {t="C", seg=17, q={2862,2973}, names={"War on the Woodpaw","A New Cloak's Sheen"}, text="The hills just west and south-west of Camp Mojache. Woodpaw Mongrels, Trappers and Brutes drop the manes; Sprite Darters flit over the same slopes and drop the wings.", zone="Feralas", map=1444, x=70.0, y=47.0},
  {t="C", seg=17, q={2975,2987}, names={"The Ogres of Feralas","Gordunni Cobalt"}, text="Ride north to the Gordunni Outpost. Kill Gordunni Ogres, Ogre Mages and Brutes; click the Gordunni Dirt Mounds around the huts for the cobalt. Frost Nova + Blizzard works well on the ogre packs.", zone="Feralas", map=1444, x=76.5, y=31.0, path={{71.0,40.0},{72.8,37.3},{75.7,37.3},{77.1,35.2},{77.3,32.2}}},
  {t="A", seg=17, q={2978}, names={"The Gordunni Scroll"}, text="A Gordunni Scroll lies on the ground in the outpost (also at 75.1, 29.7 and 80.5, 34.3). Pick it up and read it.", zone="Feralas", map=1444, x=74.5, y=27.9},
  {t="T", seg=17, q={2862}, names={"War on the Woodpaw"}, text="Back in Camp Mojache: Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="A", seg=17, q={2863}, names={"Alpha Strike"}, text="Hadoken Swiftstrider. One hour timer: start it only when you are ready to go south.", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="T", seg=17, q={2973}, names={"A New Cloak's Sheen"}, text="Krueg Skullsplitter", zone="Feralas", map=1444, x=75.9, y=42.7},
