  {t="T", seg=17, q={2975,2978}, names={"The Ogres of Feralas","The Gordunni Scroll"}, text="Rok Orhan", zone="Feralas", map=1444, x=75.8, y=43.6},
  {t="A", seg=17, q={2980,2979}, names={"The Ogres of Feralas","Dark Ceremony"}, text="Rok Orhan", zone="Feralas", map=1444, x=75.8, y=43.6},
  {t="T", seg=17, q={2987}, names={"Gordunni Cobalt"}, text="Orwin Gizzmick", zone="Feralas", map=1444, x=75.7, y=44.3},
  {t="C", seg=17, q={2974}, names={"A Grim Discovery"}, text="The Grimtotem Compound in the hills just west of the camp: Grimtotem Raiders, Naturalists and Shamans drop the horns.", zone="Feralas", map=1444, x=68.0, y=42.0},
  {t="C", seg=17, q={2863}, names={"Alpha Strike"}, text="Ride south to the big Woodpaw camps. Woodpaw Alphas walk among the Mystics and Reavers.", zone="Feralas", map=1444, x=70.4, y=54.7},
  {t="T", seg=17, q={2974}, names={"A Grim Discovery"}, text="Krueg Skullsplitter", zone="Feralas", map=1444, x=75.9, y=42.7, path={{73.6,54.9},{77.9,47.8},{78.1,45.4}}},
  {t="A", seg=17, q={2976}, names={"A Grim Discovery"}, text="Krueg Skullsplitter. He gives you a crate of horns for Belgrom Rockmaul; you hand it in on the Orgrimmar stop below.", zone="Feralas", map=1444, x=75.9, y=42.7},
  {t="T", seg=17, q={2863}, names={"Alpha Strike"}, text="Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="A", seg=17, q={2902}, names={"Woodpaw Investigation"}, text="Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="T", seg=17, q={2902}, names={"Woodpaw Investigation"}, text="The Woodpaw Battle Map lies in the gnoll camp at 71.6, 55.9", zone="Feralas", map=1444, x=71.6, y=55.9, path={{72.4,43.3},{72.4,46.0},{70.6,49.9},{70.6,54.3}}},
  {t="A", seg=17, q={2903}, names={"The Battle Plans"}, text="From the same map", zone="Feralas", map=1444, x=71.6, y=55.9},
  {t="C", seg=17, q={2980,2979}, names={"The Ogres of Feralas","Dark Ceremony"}, text="Ride south-west to the Ruins of Isildien. Gordunni Maulers stand at the north edge; Shaman and Warlocks fill the ruins. The Gordunni Orb drops from the Gordunni Mage-Lords in the southern part (around 60, 70).", zone="Feralas", map=1444, x=60.5, y=66.0, path={{70.6,62.4},{68.2,68.1},{64.8,69.0},{62.4,65.4}}},
  {t="C", seg=17, q={3520}, names={"Screecher Spirits"}, text="Screecher Spirits, on the way north-west: Vale Screechers walk the slopes between the ruins and Feral Scar Vale (57-60, 55-62), and Rogue Vale Screechers roam around the vale and north of it (48-56, 47-59). Kill one, use Yeh'kinya's Bramble on the corpse, then click the spirit that appears. You need three.", zone="Feralas", map=1444, x=57.5, y=57.0},
  {t="C", seg=17, q={2822}, names={"The Mark of Quality"}, text="Ride west to Feral Scar Vale. Feral Scar Yetis and their Enraged and Hulking kin drop the Thick Yeti Hides.", zone="Feralas", map=1444, x=53.5, y=57.0},
  {t="T", seg=17, q={2903}, names={"The Battle Plans"}, text="Back in Camp Mojache: Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="A", seg=17, q={7730,7731}, names={"Zukk'ash Infestation","Stinglasher"}, text="Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="T", seg=17, q={2980,2979}, names={"The Ogres of Feralas","Dark Ceremony"}, text="Rok Orhan", zone="Feralas", map=1444, x=75.8, y=43.6},
  {t="A", seg=17, q={3002}, names={"The Gordunni Orb"}, text="Rok Orhan. The orb goes to Uthel'nay in Orgrimmar, on the Orgrimmar stop below.", zone="Feralas", map=1444, x=75.8, y=43.6},
  {t="T", seg=17, q={2822}, names={"The Mark of Quality"}, text="Jangdor Swiftstrider. Leave his next quest, Improved Quality, until your second visit.", zone="Feralas", map=1444, x=74.4, y=42.9},
  {t="C", seg=17, q={7730,7731}, names={"Zukk'ash Infestation","Stinglasher"}, text="The Writhing Deep, the silithid hive south of the Woodpaw camps. Every Zukk'ash bug drops carapaces. Stinglasher is a big wasp that flies around the east side of the hive (around 77, 62).", zone="Feralas", map=1444, x=75.5, y=63.0, path={{72.4,43.6},{72.4,46.0},{70.6,49.9},{70.6,54.3}}},
  {t="L", seg=17, lvl=46, text="Quest XP runs short here. Keep killing Zukk'ash Workers, Wasps and Tunnelers in the hive until level 46.", zone="Feralas", map=1444, x=75.5, y=63.0},
  {t="T", seg=17, q={7730,7731}, names={"Zukk'ash Infestation","Stinglasher"}, text="Hadoken Swiftstrider", zone="Feralas", map=1444, x=74.9, y=42.5, path={{74.4,58.8},{74.4,52.8},{71.4,49.9},{72.4,43.3}}},
  {t="A", seg=17, q={7732}, names={"Zukk'ash Report"}, text="Hadoken Swiftstrider. The report goes to Zilzibin Drumlore in Orgrimmar, on the Orgrimmar stop below.", zone="Feralas", map=1444, x=74.9, y=42.5},
  {t="N", seg=17, arg="Teleport: Orgrimmar (or fly there from Camp Mojache if you don't have it)", text="Your hearthstone stays set to Camp Mojache."},
