  {t="T", seg=17, q={2976}, names={"A Grim Discovery"}, text="Belgrom Rockmaul in the Valley of Honor. He also offers Betrayed: leave it for the next segment.", zone="Orgrimmar", map=1454, x=75.2, y=34.2},
  {t="A", seg=17, q={2981}, names={"A Threat in Feralas"}, text="Belgrom Rockmaul. It only sends you to Rok Orhan; if Belgrom does not offer it because you already did the ogre quests, skip it.", zone="Orgrimmar", map=1454, x=75.2, y=34.2},
  {t="A", seg=17, q={649}, names={"Ripple Recovery"}, text="Dran Droffers in the Drag", zone="Orgrimmar", map=1454, x=59.6, y=36.5},
  {t="T", seg=17, q={2283}, names={"Necklace Recovery"}, zone="Orgrimmar", map=1454, x=59.5, y=36.6, dg=12},
  {t="T", seg=17, q={649}, names={"Ripple Recovery"}, text="Malton Droffers, right next to him", zone="Orgrimmar", map=1454, x=59.8, y=36.9},
  {t="A", seg=17, q={650}, names={"Ripple Recovery"}, text="Malton Droffers. You hand it in to Gilveradin Sunchaser in the Hinterlands.", zone="Orgrimmar", map=1454, x=59.8, y=36.9},
  {t="T", seg=17, q={7732}, names={"Zukk'ash Report"}, text="Zilzibin Drumlore, further south in the Drag (56.3, 46.7)", zone="Orgrimmar", map=1454, x=56.3, y=46.7},
  {t="T", seg=17, q={1262}, names={"Report to Zor"}, text="Zor Lonetree in the Valley of Wisdom", zone="Orgrimmar", map=1454, x=38.9, y=38.4},
