  {t="A", seg=17, q={2865}, names={"Scarab Shells"}, text="5 Uncracked Scarab Shells from the scarabs inside.", zone="Tanaris", map=1446, x=51.6, y=26.8, dg=13, req=2864},
  {t="N", seg=17, arg="Optional dungeon: Zul'Farrak, levels 44-54", text="The entrance is in the north-west corner of Tanaris, a short ride from Gadgetzan. Quests you picked up for it: Scarab Shells, Tiara of the Deep, Gahz'rilla, Troll Temper, Divino-matic Rod. Not on your path, only if you want the detour: The Prophecy of Mosh'aru (Tanaris 67, 22). The route does not come back to these hand-ins, go when it suits you: Gahz'rilla (Thousand Needles); Tiara of the Deep (Dustwallow Marsh).", zone="Tanaris", map=1446, x=38.7, y=20.1, dg=13, run=true},
  {t="T", seg=17, q={2865}, names={"Scarab Shells"}, zone="Tanaris", map=1446, x=51.6, y=26.8, dg=13},
