  {t="C", seg=17, q={10}, names={"The Scrimshank Redemption"}, text="Ride south to the Gaping Chasm. Scrimshank's Surveying Gear lies inside the silithid hive; clear the bugs at the entrance as you go in.", zone="Tanaris", map=1446, x=56.0, y=71.2},
  {t="L", seg=17, lvl=47, text="Ride west to the Dunemaul Compound. The Tanaris mobs from here on are 47-50, so grind the Dunemaul Brutes and Enforcers here until level 47. Pull them in twos and threes; Frost Nova and step back. These kills count for The Dunemaul Compound.", zone="Tanaris", map=1446, x=40.5, y=58.0, path={{50.8,71.7},{48.2,67.8},{41.0,67.2},{39.6,64.8},{38.8,59.7},{39.2,57.9}}},
  {t="C", seg=17, q={5863}, names={"The Dunemaul Compound"}, text="Finish the 10 Dunemaul Brutes and 10 Enforcers, then kill Gor'marok the Ravager (level 49), who stands near the middle at 41.5, 57.8.", zone="Tanaris", map=1446, x=40.5, y=58.0},
  {t="C", seg=17, q={2605,3362}, names={"The Thirsty Goblin","Thistleshrub Valley"}, text="Thistleshrub Valley, the cactus garden south-west of the compound. Thistleshrub Dew Collectors drop the gland; Gnarled Thistleshrubs and Rootshapers (48-50) are the kill targets. Pull them one at a time.", zone="Tanaris", map=1446, x=29.3, y=65.5, path={{38.8,58.5},{38.8,63.9},{34.0,69.6},{32.0,69.3}}},
  {t="A", seg=17, q={1560}, names={"Tooga's Quest"}, text="Tooga the turtle sits at the south end of the valley (31.8, 74.1). Accept it only when the rest of the valley is done.", zone="Tanaris", map=1446, x=31.8, y=74.1},
  {t="C", seg=17, q={1560}, names={"Tooga's Quest"}, text="30-minute timer: go straight to Torta, with no detours and no extra pulls. Lead Tooga north-east across the desert to his wife Torta, just south of Steamwheedle Port. He follows you; stay on foot, keep him close and kill anything that attacks him.", zone="Tanaris", map=1446, x=66.6, y=25.7, path={{38.0,65.7},{39.8,65.7},{40.8,67.2},{48.8,67.8},{49.2,63.0},{55.2,56.1},{54.8,45.4},{57.2,41.5},{59.0,40.6},{59.6,37.9},{64.6,31.0},{64.6,26.8}}},
  {t="T", seg=17, q={1560}, names={"Tooga's Quest"}, text="Torta", zone="Tanaris", map=1446, x=66.6, y=25.7},
  {t="T", seg=17, q={3520}, names={"Screecher Spirits"}, text="Yeh'kinya in Steamwheedle Port, just north of Torta. Skip his next quest, The Prophecy of Mosh'aru: it needs Zul'Farrak.", zone="Tanaris", map=1446, x=67.0, y=22.4},
  {t="T", seg=17, q={3527}, names={"The Prophecy of Mosh'aru"}, zone="Tanaris", map=1446, x=67.0, y=22.4, dg=13},
  {t="A", seg=17, q={4324}, names={"Yuka Screwspigot"}, text="Yorba Screwspigot in Steamwheedle Port. It sends you to Yuka in the Burning Steppes.", zone="Tanaris", map=1446, x=67.0, y=24.0, dg=16},
  {t="T", seg=17, q={10}, names={"The Scrimshank Redemption"}, text="Back in Gadgetzan: Senior Surveyor Fizzledowser", zone="Tanaris", map=1446, x=50.2, y=27.5},
