  {t="T", seg=17, q={113}, names={"Insect Part Analysis"}, text="Senior Surveyor Fizzledowser. He offers Rise of the Silithid next: leave it until you are back in Gadgetzan after the Hinterlands.", zone="Tanaris", map=1446, x=50.2, y=27.5},
