  {t="T", seg=17, q={2661}, names={"Delivery for Marin"}, text="Marin Noggenfogger. He offers Noggenfogger Elixir next: optional, no XP.", zone="Tanaris", map=1446, x=51.8, y=28.7},
  {t="A", seg=17, q={32}, names={"Rise of the Silithid"}, text="Senior Surveyor Fizzledowser. You hand the report in at Orgrimmar in the next segment.", zone="Tanaris", map=1446, x=50.2, y=27.5},
  {t="A", seg=17, q={2741}, names={"The Super Egg-O-Matic"}, text="The Super Egg-O-Matic machine, next to Andi Lynn. Its Hippogryph Egg lies in nests in southern Feralas; you put the egg in the machine on the next segment's Gadgetzan stop.", zone="Tanaris", map=1446, x=52.4, y=27.0},
  {t="FLY", seg=17, arg="Camp Mojache"},
  {t="S", seg=17, arg="Camp Mojache", text="Innkeeper Greul"},
