  {t="C", seg=18, q={4292}, names={"The Bait for Lar'korwi"}, text="Ride south along the eastern ridge past the Eastern Pylon to the ledge covered in big bones. Open Torwa's Pouch, put the meat on the flat rock and use the pheromone mixture on it. Lar'korwi (level 56) charges in: Frost Nova and kite", zone="Un'Goro Crater", map=1449, x=79.9, y=49.9, path={{70.0,13.9},{69.8,22.6},{71.0,24.4},{71.0,29.8},{74.0,34.3},{75.5,39.1},{76.1,46.6}}},
