  {t="T", seg=18, q={3782}, names={"Morrowgrain Research"}, text="Bashana Runetotem, also on Elder Rise", zone="Thunder Bluff", map=1456, x=71.1, y=34.2},
  {t="A", seg=18, q={3786}, names={"Morrowgrain Research"}, text="She gives you the Evergreen Pouch. Buy about 15 Packets of Tharlendis Seeds from her. Use the pouch (1 seed and 2 soil) every 10 minutes from now on; you hand in 10 Morrowgrain on your next Thunder Bluff stop", zone="Thunder Bluff", map=1456, x=71.1, y=34.2},
  {t="N", seg=18, arg="Teleport: Orgrimmar (or fly there if you don't have it)"},
