  {t="A", seg=18, q={5535,5536}, names={"Spiritual Unrest","A Land Filled with Hatred"}, text="Ride east out of Splintertree on the road into Azshara. The road passes near Forest Song, an Alliance outpost, so give its guards room. Loh'atu camps just inside the Azshara border", zone="Azshara", map=1447, x=11.4, y=78.2},
  {t="C", seg=18, q={5535}, names={"Spiritual Unrest"}, text="Highborne Apparitions and Lichlings haunt the Shadowsong Shrine, north-east of Loh'atu", zone="Azshara", map=1447, x=16.4, y=70.0},
  {t="C", seg=18, q={5536}, names={"A Land Filled with Hatred"}, text="Haldarr satyrs, tricksters and felsworn in the satyr camp further north-east", zone="Azshara", map=1447, x=20.1, y=61.8},
  {t="T", seg=18, q={5535,5536}, names={"Spiritual Unrest","A Land Filled with Hatred"}, text="Loh'atu", zone="Azshara", map=1447, x=11.4, y=78.2},
