  {t="T", seg=18, q={8250}, names={"Magecraft"}, text="Sanath Lim-yo, at the foot of the cliffs just east of Valormok. Handing it in teleports you up to Archmage Xylem's tower", zone="Azshara", map=1447, x=28.1, y=50.1},
  {t="A", seg=18, q={8251}, names={"Magic Dust"}, text="Archmage Xylem, at the top of the tower", zone="Azshara", map=1447, x=29.2, y=40.2},
  {t="N", seg=18, arg="Talk to Nyrill at the tower to be sent back down to Sanath's camp"},
  {t="N", seg=18, arg="Back at Sanath's camp: if he offers A Meeting with the Master, take it; the logger records it", text="New in Forever: he wants 2 Undamaged Hippogryph Feathers before he sends you up again. Thunderhead Hippogryphs around his camp and Valormok (15-21, 49-66), Stagwings and the Skystormers around the blood elf camp (47-64, 14-38) drop them. If he does not offer it, his repeatable Meeting with the Master sends you up whenever you ask, and Nyrill's Return Trip brings you down"},
  {t="A", seg=18, q={3601}, names={"Kim'jael Indeed!"}, text="Kim'jael, far to the north-east. Follow the road east, then north", zone="Azshara", map=1447, x=53.5, y=21.8, path={{30.4,42.1},{34.2,43.0},{38.4,37.3},{43.8,37.0},{48.0,31.6},{48.2,28.0}}},
  {t="C", seg=18, q={3505,8251,3601}, names={"Betrayed","Magic Dust","Kim'jael Indeed!"}, text="The blood elf camp on the bluffs south of Kim'jael. Reclaimers and Surveyors drop Glittering Dust, and Kim'jael's Equipment boxes lie on the ground in the camp. Frost Nova and Blizzard the groups. If Sanath asked for feathers, also kill the Thunderhead Skystormers and Stagwings around the camp until 2 Undamaged Hippogryph Feathers drop", zone="Azshara", map=1447, x=57.0, y=28.5},
  {t="T", seg=18, q={3505}, names={"Betrayed"}, text="Magus Rimtori's camp, a ring of crystals at the east end: read the Kaldorei Tome of Summoning", zone="Azshara", map=1447, x=59.5, y=31.3},
  {t="A", seg=18, q={3506}, names={"Betrayed"}, text="The Kaldorei Tome of Summoning", zone="Azshara", map=1447, x=59.5, y=31.3},
  {t="C", seg=18, q={3506}, names={"Betrayed"}, text="Clear the camp, then destroy the Arcane Focusing Crystal next to the tome. Magus Rimtori (level 55) appears; kill her and loot her head", zone="Azshara", map=1447, x=59.5, y=31.4},
  {t="T", seg=18, q={3601}, names={"Kim'jael Indeed!"}, text="Kim'jael", zone="Azshara", map=1447, x=53.5, y=21.8},
  {t="A", seg=18, q={5534}, names={"Kim'jael's \"Missing\" Equipment"}, zone="Azshara", map=1447, x=53.5, y=21.8},
  {t="T", seg=18, q={8251}, names={"Magic Dust"}, text="Ride back west to Sanath. Give him the 2 feathers if he asked for them, then ask him to send you up: Archmage Xylem", zone="Azshara", map=1447, x=29.2, y=40.2, path={{48.2,28.0},{48.0,31.6},{43.8,37.0},{38.4,37.3},{34.2,43.0},{30.4,42.1}}},
