  {t="A", seg=19, q={5084}, names={"Falling to Corruption"}, text="Keep it: the cauldron is in Felwood and you pass it on your second visit", zone="Winterspring", map=1452, x=31.3, y=45.2},
  {t="C", seg=19, q={4521}, obj={2}, names={"Wild Guardians"}, text="Ragged Owlbeasts in the woods east of the hot springs", zone="Winterspring", map=1452, x=46.5, y=44.0, path={{30.4,43.9},{30.8,40.9},{39.4,39.1},{40.8,39.1},{42.0,42.1},{45.2,42.1}}},
  {t="C", seg=19, q={4842}, names={"Strange Sources"}, text="Ride to the far south until the sky turns dark at Darkwhisper Gorge. Reaching the mouth of the gorge is enough; the demons further in are elite", zone="Winterspring", map=1452, x=59.8, y=74.3},
  {t="G", seg=19, text="Ride north to Everlook", zone="Winterspring", map=1452, x=60.4, y=36.4},
