  {t="S", seg=19, arg="Everlook", text="Innkeeper Vizzie. You hearth back here later"},
  {t="A", seg=19, q={6603}, names={"Trouble in Winterspring!"}, text="Meggi Peppinrocker. It goes to Donova on your next pass", zone="Winterspring", map=1452, x=60.7, y=38.2},
