  {t="C", seg=19, q={8464}, names={"Winterfall Activity"}, text="Winterfall Village, just east of Everlook: Shaman, Den Watchers and Ursa. High Chief Winterfall in the big cave is elite: stay out of it", zone="Winterspring", map=1452, x=67.0, y=37.0, path={{68.2,41.3}}, cave=true},
  {t="L", seg=19, lvl=56, text="Stay in Winterfall Village and grind to 56 before the yetis: the furbolg packs are ideal for Frost Nova and Blizzard. Being 56 also lets you take Rabine's Silithus quest in Moonglade later, and it shortens the grind before the Plaguelands", zone="Winterspring", map=1452, x=67.0, y=37.0},
  {t="C", seg=19, q={3783}, names={"Are We There, Yeti?"}, text="Ice Thistle Yetis on the hills south-east of the village drop Thick Yeti Furs", zone="Winterspring", map=1452, x=67.5, y=44.0, path={{65.6,37.6},{65.6,40.0},{66.4,43.6}}},
  {t="T", seg=19, q={3783}, names={"Are We There, Yeti?"}, text="Umi Rumplesnicker, Everlook", zone="Winterspring", map=1452, x=60.9, y=37.6},
