  {t="C", seg=19, q={977}, names={"Are We There, Yeti?"}, text="Ice Thistle Matriarchs and Patriarchs (level 56-58) higher up in the Ice Thistle Hills. Pull them one at a time", zone="Winterspring", map=1452, x=69.0, y=41.0},
  {t="T", seg=19, q={977}, names={"Are We There, Yeti?"}, text="Umi Rumplesnicker", zone="Winterspring", map=1452, x=60.9, y=37.6},
