  {t="C", seg=19, q={5082,5082}, obj={1,3}, names={"Threat of the Winterfall","Threat of the Winterfall"}, text="The Winterfall camp east of Donova: Pathfinders and Totemics (the camp near Salfa has more of both). Kill the one Den Watcher here too (1 of 8). Only 4 Den Watchers stand in the west, so you clear both camps twice for the 8", zone="Winterspring", map=1452, x=41.0, y=44.0},
  {t="N", seg=19, arg="Go back through Timbermaw Hold into Felwood for the Toxic Horrors", text="On the way, kill the three Winterfall Den Watchers at the camp just south-east of Salfa (around 30.5, 36): 4 of 8"},
