  {t="N", seg=19, arg="Go back through Timbermaw Hold to Winterspring", text="Neutral with Timbermaw and carrying a Ritual Totem? Hand it to Kernda inside the Hold now (8470 / 8471). Didn't get Meilosh's Runecloth quest earlier? Try again now"},
  {t="N", seg=19, arg="Kill the 3 Den Watchers at the camp just south-east of Salfa (30.5, 36.3) again: they have respawned since you passed", text="That makes 7 of 8. Spare beads? Salfa is right there"},
