  {t="C", seg=19, q={5542,6042}, names={"Demon Dogs","Un-Life's Little Annoyances"}, text="Frenzied Plaguehounds in the north (around 52, 23) and the other hounds along the roads; Monstrous Plaguebats in the north (around 48, 35) and Noxious Plaguebats around Light's Hope", zone="Eastern Plaguelands", map=1423, x=43.9, y=28.9},
  {t="C", seg=19, q={5901,5211}, names={"A Plague Upon Thee","Defenders of Darrowshire"}, text="Plaguewood, in the north-west: use the Empty Termite Jar on the Large Termite Mounds until you have 100 termites. The Cannibal Ghouls all over Plaguewood release Darrowshire Spirits: free the rest of your 15 here", zone="Eastern Plaguelands", map=1423, x=18.0, y=25.0},
