  {t="A", seg=19, q={8859}, names={"Secrets of the Colossus - Zora"}, text="Colossus Researcher Sophia, inside Cenarion Hold. Her husk goes to Light's Hope Chapel, where the route ends if you are short of 60. Nestor and Eazel next to her offer husks for Booty Bay (8857) and Thorium Point (8858), about 10,000 XP each: take them only if you plan to fly there at the end", zone="Silithus", map=1451, x=49.5, y=37.4},
  {t="A", seg=19, q={9416}, names={"Report to General Kirika"}, text="Scout Bloodfist, in Cenarion Hold. General Kirika is south of the Hold; you pass the camp later", zone="Silithus", map=1451, x=49.0, y=36.7},
