  {t="C", seg=19, q={9422}, names={"Scouring the Desert"}, text="Click the Silithyst on the geyser beside Ortell's hut (another geyser is at 60.6, 63.0) and walk it west to the Silithyst Extractor in Kirika's camp. Mounting drops it, and carrying it flags you for PvP. No Silithyst on either geyser? Skip this and the next step", zone="Silithus", map=1451, x=64.0, y=70.9},
  {t="T", seg=19, q={9422}, names={"Scouring the Desert"}, text="General Kirika", zone="Silithus", map=1451, x=50.8, y=69.5},
  {t="C", seg=19, q={8318}, names={"Secret Communication"}, text="The Twilight Post around Twilight Keeper Havunth, south-west of Cenarion Hold: Twilight Avengers, Geolords and Stonecallers. Collect 10 more Encrypted Twilight Texts for Bor", zone="Silithus", map=1451, x=39.0, y=43.5},
