  {t="T", seg=19, q={8859}, names={"Secrets of the Colossus - Zora"}, text="Not 60 yet? Fly from the Undercity to Light's Hope Chapel and hand Zora's husk to Lord Maxwell Tyrosus", zone="Eastern Plaguelands", map=1423, x=71.9, y=48.4},
  {t="L", seg=19, lvl=60, text="Finish at Corin's Crossing, just west of Light's Hope. Rather fly than grind? If you took Nestor's and Eazel's husks, Overseer Oilfist at Thorium Point (Searing Gorge flight path) takes 8858 and Oglethorpe Obnoticus in Booty Bay takes 8857, about 10,000 XP each", zone="Eastern Plaguelands", map=1423, x=52.0, y=57.0},
